window.BANQUE_INFINI = {"module":"annee-2/theorique/semestre-1/mf-2","titre":"Mouvement & Fonction II","sources":[{"t":"Contrôle moteur et mouvement humain","q":"cours-01-controle-moteur/quiz.html","f":"cours-01-controle-moteur/fiche.html"},{"t":"Le système somatosensoriel","q":"cours-02-systeme-somatosensoriel/quiz.html","f":"cours-02-systeme-somatosensoriel/fiche.html"},{"t":"Les systèmes visuel et vestibulaire","q":"cours-03-systemes-visuel-vestibulaire/quiz.html","f":"cours-03-systemes-visuel-vestibulaire/fiche.html"},{"t":"Le cortex cérébral","q":"cours-04-cortex-cerebral/quiz.html","f":"cours-04-cortex-cerebral/fiche.html"},{"t":"Le cervelet","q":"cours-05-cervelet/quiz.html","f":"cours-05-cervelet/fiche.html"},{"t":"Les noyaux gris centraux","q":"cours-06-noyaux-gris-centraux/quiz.html","f":"cours-06-noyaux-gris-centraux/fiche.html"},{"t":"La neuroplasticité","q":"cours-07-neuroplasticite/quiz.html","f":"cours-07-neuroplasticite/fiche.html"},{"t":"L'apprentissage moteur","q":"cours-08-apprentissage-moteur/quiz.html","f":"cours-08-apprentissage-moteur/fiche.html"}],"questions":[{"q":"Comment définit-on le contrôle moteur ?","o":["La capacité de réguler ou de diriger les mécanismes essentiels au mouvement","La force maximale d'un muscle","L'amplitude articulaire disponible","La vitesse de conduction nerveuse"],"r":0,"e":"Il implique différents systèmes, différentes étapes et différentes structures.","s":0},{"q":"Quel est l'objectif général de l'étude du contrôle moteur ?","o":["Étudier la nature du mouvement et la façon dont il est planifié et contrôlé","Mesurer la force musculaire","Classer les pathologies neurologiques","Décrire l'anatomie du SNC"],"r":0,"e":"Il s'agit de comprendre les mécanismes neurophysiologiques à la base du mouvement humain.","s":0},{"q":"Pourquoi le contrôle moteur est-il important pour le kinésithérapeute ?","o":["Parce qu'il travaille avec le mouvement : c'est la base pour interpréter le comportement moteur et fonder l'intervention","Parce qu'il permet de poser un diagnostic médical","Parce qu'il remplace l'imagerie","Parce qu'il détermine le pronostic vital"],"r":0,"e":"Il fonde l'interprétation du comportement moteur.","s":0},{"q":"Quelle est la première étape de la chaîne du contrôle moteur ?","o":["L'intention, la décision et la motivation","L'analyse de l'information sensorielle","Le traitement","L'exécution de la réponse motrice"],"r":0,"e":"Vient ensuite l'analyse et l'interprétation de l'information sensorielle.","s":0},{"q":"D'où émergent les commandes motrices ?","o":["De transformations sensori-motrices","De la contraction musculaire","Des récepteurs articulaires seuls","De la moelle épinière uniquement"],"r":0,"e":"Elles s'appuient sur une information anticipatoire (feedforward) et instantanée (feedback).","s":0},{"q":"Qu'est-ce que le feedforward dans l'analyse du mouvement ?","o":["Une information sensorielle anticipatoire","Une information sensorielle instant par instant","Une réponse réflexe","Une correction rétroactive"],"r":0,"e":"Le feedback correspond à l'information instant par instant.","s":0},{"q":"Quelles sont les caractéristiques du mouvement volontaire selon l'axe activité/stabilité ?","o":["Conscient et intentionnel — il relève de l'ACTIVITÉ","Inconscient et polysegmentaire","Il précède et accompagne le contrôle postural","Il relève de la STABILITÉ"],"r":0,"e":"Le contrôle postural relève de la stabilité : inconscient, polysegmentaire, il précède et accompagne le mouvement volontaire.","s":0},{"q":"Quels sont les quatre types de mouvement humain ?","o":["Réflexe, rythmique, volontaire et activité posturale","Concentrique, excentrique, isométrique, isocinétique","Actif, passif, résisté, assisté","Statique, dynamique, balistique, continu"],"r":0,"e":"Ils peuvent être réalisés par les mêmes groupes musculaires mais diffèrent dans leur traitement.","s":0},{"q":"Comment définit-on le mouvement réflexe ?","o":["Une réponse simple et stéréotypée à un stimulus spécifique, générée par un circuit neural simple médullaire ou du tronc cérébral","Un mouvement conscient et intentionnel","Un mouvement dont le timing est contrôlé par des CPG","Un ajustement postural anticipatoire"],"r":0,"e":"Il est involontaire et inné.","s":0},{"q":"Quelles classifications s'appliquent aux mouvements réflexes ?","o":["Monosynaptiques ou polysynaptiques, homolatéraux ou hétérolatéraux, segmentaires ou intersegmentaires","Statiques ou dynamiques","Rapides ou lents","Corticaux ou sous-corticaux"],"r":0,"e":"Exemples : réflexe myotatique, réflexe cutané de retrait, réflexe vestibulo-oculaire.","s":0},{"q":"Quel est l'avantage du mouvement réflexe ?","o":["Il agit comme mécanisme protecteur, déclenché sans planification, avec une réponse plus rapide et efficiente","Il permet un apprentissage rapide","Il est modulable volontairement","Il est le plus économique"],"r":0,"e":"C'est une réponse simple et stéréotypée.","s":0},{"q":"Que sont les générateurs de patron centraux (CPG) ?","o":["Des réseaux neuronaux du SNC capables de générer un patron rythmique","Des récepteurs musculaires","Des aires corticales de planification","Des noyaux vestibulaires"],"r":0,"e":"Ils activent différents groupes de neurones moteurs fonctionnant souvent de façon réciproque.","s":0},{"q":"Quels mouvements relèvent des générateurs de patron centraux ?","o":["Marche, course, déglutition et respiration","Écrire et jouer d'un instrument","Le réflexe myotatique","Les ajustements posturaux anticipatoires"],"r":0,"e":"Ces mouvements peuvent être contrôlés volontairement, mais leur timing et leur organisation spatiale sont autonomes.","s":0},{"q":"Où se situent les circuits contrôlant le timing des mouvements rythmiques ?","o":["Dans la moelle épinière ou le tronc cérébral","Dans le cortex préfrontal","Dans le cervelet uniquement","Dans les noyaux gris centraux uniquement"],"r":0,"e":"Ce sont les générateurs de patron centraux.","s":0},{"q":"De quelle structure dépend le mouvement volontaire ?","o":["Du cortex, par un contrôle conscient","Du tronc cérébral","De la moelle épinière","Des noyaux vestibulaires"],"r":0,"e":"Il est intentionnel, initié par une décision interne d'agir.","s":0},{"q":"Comment évolue le mouvement volontaire ?","o":["Sa nature et son efficacité s'améliorent avec l'expérience et l'apprentissage ; il peut être automatisé par la répétition","Il reste stéréotypé","Il devient réflexe","Il ne se modifie pas"],"r":0,"e":"Son contrôle neural implique des processus sensoriels, cognitifs et perceptifs.","s":0},{"q":"Quels processus, outre les processus moteurs, interviennent dans le mouvement volontaire ?","o":["Sensoriels, cognitifs et perceptifs","Uniquement métaboliques","Uniquement vasculaires","Aucun autre"],"r":0,"e":"Il est dépendant d'un contrôle conscient cortical.","s":0},{"q":"Quelles structures assurent principalement le contrôle postural ?","o":["Le tronc cérébral et le cervelet","Le cortex préfrontal","La moelle épinière seule","Les noyaux gris centraux seuls"],"r":0,"e":"Le cortex peut y contribuer via les aires de planification motrice.","s":0},{"q":"Quelles sont les caractéristiques du contrôle postural ?","o":["Majoritairement inconscient, multisegmentaire et bilatéral","Conscient et intentionnel","Monosegmentaire","Uniquement réflexe et médullaire"],"r":0,"e":"Il précède et accompagne le mouvement volontaire.","s":0},{"q":"Dans quelles situations le cortex contribue-t-il au contrôle postural ?","o":["Ajustements posturaux anticipatoires, apprentissage de nouvelles stratégies posturales et nécessité d'attention (dual task)","Uniquement pendant le sommeil","Jamais","Uniquement en cas de lésion médullaire"],"r":0,"e":"Ces contributions passent par les aires de planification motrice.","s":0},{"q":"Quels muscles peuvent agir comme muscles posturaux ?","o":["N'importe quel groupe musculaire, selon les parties du corps en contact avec l'environnement et les exigences biomécaniques de la tâche","Uniquement les érecteurs du rachis","Uniquement les abdominaux","Uniquement les muscles antigravitaires des membres inférieurs"],"r":0,"e":"C'est ce qui définit la notion de stratégie posturale.","s":0},{"q":"Quelle caractéristique du mouvement humain traduit son efficience ?","o":["Il est économique","Il est rapide","Il est puissant","Il est réflexe"],"r":0,"e":"Il est aussi dirigé vers un objectif, adapté et coordonné dans l'espace et dans le temps.","s":0},{"q":"Sur quoi repose un mouvement contrôlé, économique, coordonné et adapté ?","o":["Sur la stabilité, c'est-à-dire un contrôle postural qui anticipe et s'adapte","Sur la force maximale","Sur la vitesse d'exécution","Sur l'amplitude articulaire"],"r":0,"e":"Le contrôle postural garantit l'absence de perturbation.","s":0},{"q":"Quelles sont les deux fonctions du contrôle postural ?","o":["L'orientation et la stabilité","La force et l'endurance","La coordination et la vitesse","La perception et la cognition"],"r":0,"e":"Il repose sur une activité motrice permanente activant les stratégies posturales nécessaires.","s":0},{"q":"Quels sont les trois facteurs qui influencent le mouvement ?","o":["L'individu, la tâche et l'environnement","La force, la vitesse et l'amplitude","Le cortex, le cervelet et les noyaux gris","La perception, la cognition et l'action"],"r":0,"e":"Référence : Shumway-Cook & Woollacott, 2011.","s":0},{"q":"Quelles caractéristiques individuelles influencent la performance du mouvement ?","o":["Contexte socio-culturel, âge, état général et émotionnel, structures musculo-squelettiques et neurales, expérience motrice et clinique","Uniquement l'âge","Uniquement la force musculaire","Uniquement la motivation"],"r":0,"e":"L'individu agit par perception, cognition et action.","s":0},{"q":"Quels sont les trois axes d'action de l'individu selon le modèle de Shumway-Cook ?","o":["Perception, cognition et action","Force, souplesse et endurance","Feedback, feedforward et réflexe","Stabilité, mobilité et coordination"],"r":0,"e":"Ils interagissent avec la tâche et l'environnement.","s":0},{"q":"Quels types de tâches régulent les mécanismes de contrôle du mouvement ?","o":["Volontaire/cognitif/intentionnel, rythmique/continu, volontaire balistique, automatique et postural","Statique et dynamique seulement","Concentrique et excentrique","Analytique et fonctionnel"],"r":0,"e":"Le type de tâche régule les mécanismes qui contrôlent le mouvement.","s":0},{"q":"Comment distingue-t-on les caractéristiques de l'environnement ?","o":["En caractéristiques régulatrices et non régulatrices","En caractéristiques internes et externes","En caractéristiques stables et instables","En caractéristiques visuelles et auditives"],"r":0,"e":"Les caractéristiques régulatrices contraignent directement le mouvement.","s":0},{"q":"Que caractérise une tâche volontaire balistique ?","o":["Elle possède un début et une fin","Elle est continue et rythmique","Elle est automatique","Elle est posturale"],"r":0,"e":"Les tâches rythmiques sont au contraire continues.","s":0},{"q":"Les commandes motrices émergent, selon le cours, de :","o":["La seule volonté consciente","Transformations sensori-motrices, à partir d'une information anticipatoire (feedforward) et instant par instant (feedback)","Réflexes médullaires","L'activité du cervelet seul"],"r":1,"e":"Cette double source explique qu'un mouvement puisse être à la fois préparé à l'avance et corrigé en cours d'exécution.","s":0},{"q":"Un mouvement réflexe peut être classé comme :","o":["Monosynaptique ou polysynaptique, homolatéral ou hétérolatéral, segmentaire ou intersegmentaire","Conscient ou inconscient","Rapide ou lent","Simple ou complexe uniquement"],"r":0,"e":"Ces trois axes de classement se combinent : un même réflexe peut être polysynaptique, hétérolatéral et intersegmentaire, comme le retrait à la douleur.","s":0},{"q":"L'avantage du mouvement réflexe tient à ce qu'il est :","o":["Modifiable par apprentissage","Déclenché sans nécessité de planification, produisant une réponse plus rapide et efficiente","Conscient et contrôlable","Généré par le cortex"],"r":1,"e":"Il agit comme mécanisme protecteur : la protection doit être immédiate, ce qu'un circuit passant par le cortex ne permettrait pas.","s":0},{"q":"Les générateurs de patron centraux sont décrits comme :","o":["Des réseaux neuronaux du SNC capables de générer un patron rythmique, parfois divisé en phases","Des récepteurs périphériques","Des aires corticales","Des noyaux du thalamus"],"r":0,"e":"Ils activent différents groupes de neurones moteurs fonctionnant souvent de façon réciproque, ce qui produit l'alternance caractéristique de la marche.","s":0},{"q":"Parmi les mouvements relevant des générateurs de patron centraux, le cours cite :","o":["L'écriture","La marche, la course, la déglutition et la respiration","Le geste sportif technique","Le réflexe myotatique"],"r":1,"e":"Ces mouvements peuvent être contrôlés volontairement, mais leur timing et leur organisation spatiale sont pris en charge de façon autonome par les circuits médullaires ou du tronc cérébral.","s":0},{"q":"Le mouvement volontaire dépend :","o":["De la moelle épinière","D'un contrôle conscient par le cortex","Du tronc cérébral","Des récepteurs articulaires"],"r":1,"e":"Il est intentionnel, initié par une décision interne d'agir, idéalisé, et sa nature comme son efficacité s'améliorent avec l'expérience et l'apprentissage.","s":0},{"q":"Outre les processus moteurs, le contrôle neural du mouvement volontaire implique :","o":["Des processus sensoriels, cognitifs et perceptifs","Uniquement des processus réflexes","Des processus végétatifs","Des processus hormonaux"],"r":0,"e":"Le mouvement volontaire peut en outre être automatisé par la répétition, ce qui réduit progressivement la charge cognitive qu'il exige.","s":0},{"q":"Le contrôle postural est assuré principalement par :","o":["Le cortex moteur primaire","Le tronc cérébral et le cervelet","Les noyaux gris centraux","La moelle épinière seule"],"r":1,"e":"Il relève d'une inter-relation dynamique et dépendante du contexte entre plusieurs niveaux du système nerveux central.","s":0},{"q":"Les caractéristiques du contrôle postural comprennent le fait qu'il est :","o":["Conscient et unilatéral","Majoritairement inconscient, multisegmentaire et bilatéral","Purement réflexe","Limité au tronc"],"r":1,"e":"Il précède et accompagne le mouvement volontaire : les ajustements posturaux anticipatoires se déclenchent avant même le début du geste.","s":0},{"q":"Le cortex contribue au contrôle postural :","o":["En permanence","Par ses aires de planification motrice, notamment pour les ajustements posturaux anticipatoires","Uniquement pendant le sommeil","Jamais"],"r":1,"e":"C'est ce qui explique qu'une lésion corticale puisse altérer l'anticipation posturale sans abolir les réactions posturales automatiques.","s":0},{"q":"Les deux fonctions du contrôle postural sont :","o":["L'orientation et l'équilibre","La force et l'endurance","La vitesse et la précision","La coordination et la dextérité"],"r":0,"e":"L'orientation situe le corps par rapport à l'environnement et à la tâche ; l'équilibre maintient le centre de masse dans la base de sustentation.","s":0},{"q":"Selon le modèle de Shumway-Cook et Woollacott (2011), le mouvement résulte de l'interaction entre :","o":["L'individu, la tâche et l'environnement","Le cortex, le cervelet et les noyaux gris","La force, la vitesse et la précision","Les afférences, le traitement et les efférences"],"r":0,"e":"Ce triangle est le cadre de référence du module : modifier l'un des trois pôles modifie le mouvement produit, ce qui ouvre autant de leviers d'intervention.","s":0},{"q":"Les caractéristiques de l'environnement se distinguent, dans ce modèle, en :","o":["Régulatrices et non régulatrices","Physiques et sociales","Internes et externes","Stables et instables"],"r":0,"e":"Les caractéristiques régulatrices contraignent directement la forme du mouvement ; les non régulatrices ne l'affectent qu'indirectement.","s":0},{"q":"Une tâche volontaire balistique se caractérise par :","o":["Une correction continue en cours d'exécution","Une exécution trop rapide pour permettre une correction par feedback, reposant sur une programmation préalable","Une lenteur permettant l'ajustement","Une absence de planification"],"r":1,"e":"C'est précisément pourquoi le feedforward y est déterminant : la commande est émise en bloc, sans possibilité de rattrapage en cours de geste.","s":0},{"q":"Un mouvement contrôlé, économique, coordonné et adapté repose selon le cours sur :","o":["La force musculaire seule","L'intégration des informations sensorielles et l'organisation de la réponse motrice","La vitesse d'exécution","La répétition mécanique"],"r":1,"e":"L'efficience du mouvement humain se lit précisément dans ce rapport entre le résultat obtenu et l'énergie dépensée pour l'obtenir.","s":0},{"q":"L'étude du contrôle moteur importe au kinésithérapeute parce qu'elle :","o":["Est exigée par la réglementation","Constitue la base pour interpréter le comportement moteur et fonde l'intervention","Permet de poser un diagnostic médical","Remplace l'examen clinique"],"r":1,"e":"Le kinésithérapeute travaille avec le mouvement : sans modèle de ce qui le produit, l'observation clinique resterait descriptive.","s":0},{"q":"La première étape de la chaîne du contrôle moteur est :","o":["L'analyse de l'information sensorielle","L'intention, la décision et la motivation","Le traitement","L'exécution"],"r":1,"e":"Suivent l'analyse et l'interprétation de l'information sensorielle, le traitement, puis l'exécution de la réponse motrice la plus adaptée.","s":0},{"q":"Les mouvements réflexes cités en exemple par le cours incluent :","o":["Le réflexe myotatique inverse, le réflexe cutané de retrait et le réflexe vestibulo-oculaire","La marche et la course","L'écriture","Le geste sportif"],"r":0,"e":"S'y ajoutent les réflexes des récepteurs articulaires. Marche et course relèvent des mouvements rythmiques, l'écriture du mouvement volontaire.","s":0},{"q":"Le circuit générant un mouvement réflexe se situe :","o":["Dans le cortex moteur","Au niveau de la moelle épinière ou du tronc cérébral","Dans le cervelet","Dans les noyaux gris centraux"],"r":1,"e":"Sa simplicité est la condition de sa rapidité : plus le circuit est court, plus la réponse est précoce.","s":0},{"q":"Le mouvement volontaire est qualifié d'« idéalisé » parce qu'il :","o":["Est toujours parfait","Est représenté mentalement avant d'être exécuté","Ne dépend pas du cortex","Est identique chez tous"],"r":1,"e":"Cette représentation préalable est ce qui permet de comparer le résultat obtenu à l'intention de départ — base de la correction d'erreur assurée par le cervelet.","s":0},{"q":"Pourquoi la compréhension du traitement sensoriel est-elle importante pour le contrôle moteur ?","o":["Parce que toutes les actions génèrent un feedback sensoriel et que les systèmes sensoriels guident et ajustent le mouvement","Parce qu'ils remplacent la commande motrice","Parce qu'ils produisent la contraction musculaire","Parce qu'ils déterminent la force"],"r":0,"e":"Ils permettent aussi l'apprentissage de nouvelles compétences et d'éviter les lésions.","s":1},{"q":"Quels sont les trois inputs sensoriels ajustant la réponse du SNC au contexte ?","o":["Somatosensoriel, visuel et vestibulaire","Visuel, auditif et tactile","Proprioceptif, nociceptif et thermique","Cutané, articulaire et musculaire"],"r":0,"e":"Les représentations sensorielles permettent de planifier, coordonner et exécuter les programmes moteurs.","s":1},{"q":"Qu'est-ce que le schéma corporel ?","o":["La représentation interne du corps et de son orientation dans l'espace","La somme des dermatomes","La carte des champs sensitifs cutanés","L'image visuelle de soi"],"r":0,"e":"Il repose sur l'ensemble des systèmes sensoriels.","s":1},{"q":"À quelles 4 modalités le système somatosensoriel est-il sensible ?","o":["Toucher discriminatif, température, douleur et proprioception","Vision, audition, toucher et équilibre","Pression, vibration, chaleur et froid","Toucher, douleur, vibration et goût"],"r":0,"e":"Les trois premières relèvent de l'innervation cutanée, la proprioception de l'innervation articulaire et musculaire.","s":1},{"q":"Quels récepteurs détectent le chaud et le froid ?","o":["Les thermorécepteurs","Les mécanorécepteurs","Les nocicepteurs","Les propriocepteurs"],"r":0,"e":"Les mécanorécepteurs détectent toucher, pression, allongement et vibration.","s":1},{"q":"Qu'est-ce qu'un champ sensitif ?","o":["La zone innervée par un seul neurone sensitif","La surface d'un dermatome","La zone de projection corticale","L'aire innervée par un nerf périphérique"],"r":0,"e":"Il est plus petit en distal et plus grand en proximal.","s":1},{"q":"Pourquoi distingue-t-on deux stimuli proches sur la pulpe d'un doigt et non sur le tronc ?","o":["Parce que les zones distales ont une plus grande densité de récepteurs et des champs sensitifs plus petits","Parce que le tronc n'a pas de récepteurs","Parce que la conduction y est plus lente","Parce que le cortex ignore le tronc"],"r":0,"e":"Les champs sensitifs sont plus petits en distal.","s":1},{"q":"Quel est l'effet du contact de la main avec une surface ?","o":["Il augmente l'input sensoriel, influence le contrôle postural et renforce le schéma corporel et l'orientation posturale","Il diminue la proprioception","Il inhibe les récepteurs articulaires","Il n'a aucun effet"],"r":0,"e":"La main est l'une des zones à la plus grande densité sensitive.","s":1},{"q":"Où se situent les récepteurs de l'innervation articulaire ?","o":["Dans la capsule articulaire, la synoviale et les ligaments","Dans le tendon uniquement","Dans le cartilage","Dans la moelle osseuse"],"r":0,"e":"Ce sont des mécanorécepteurs et des terminaisons libres.","s":1},{"q":"Quand les récepteurs articulaires déchargent-ils au maximum ?","o":["Lorsque l'articulation se trouve à ses angles extrêmes","En position neutre","À mi-amplitude","Au repos"],"r":0,"e":"Ils envoient de l'information à tout angle, mais leur fréquence maximale se situe aux extrêmes.","s":1},{"q":"Quel effet réflexe ont les récepteurs articulaires ?","o":["Une inhibition réflexe des agonistes et une facilitation des antagonistes","Une facilitation des agonistes","Une inhibition des antagonistes","Aucun effet moteur"],"r":0,"e":"Ils sont considérés comme moins importants qu'on ne le pensait auparavant.","s":1},{"q":"Comment les fuseaux neuromusculaires sont-ils disposés par rapport aux fibres musculaires ?","o":["Parallèlement aux fibres des muscles squelettiques","En série avec le tendon","Perpendiculairement","Dans l'aponévrose"],"r":0,"e":"L'OTG est quant à lui situé à la jonction myotendineuse.","s":1},{"q":"Combien de fibres intrafusales contient environ un FNM ?","o":["12","4","30","100"],"r":0,"e":"Leurs extrémités sont reliées aux fibres extrafusales.","s":1},{"q":"Sur quoi le FNM informe-t-il le SNC ?","o":["Les variations de longueur musculaire et la vitesse de ces variations","La tension du tendon","La force de contraction","La température musculaire"],"r":0,"e":"L'OTG informe sur la force de la contraction musculaire.","s":1},{"q":"Quelles fibres intrafusales sont plus sensibles à l'étirement rapide ?","o":["Les fibres à sac","Les fibres à chaîne","Les fibres extrafusales","Les deux également"],"r":0,"e":"Les fibres à chaîne sont plus sensibles à l'étirement prolongé et maintenu.","s":1},{"q":"Quelle partie des fibres intrafusales n'est pas contractile ?","o":["La portion centrale","Les extrémités","Toute la fibre","Aucune partie"],"r":0,"e":"C'est l'organisation des noyaux dans la portion centrale qui différencie fibres à sac et à chaîne.","s":1},{"q":"Que renseignent les fibres afférentes Ia ?","o":["La vitesse de l'étirement, étant plus sensibles aux étirements rapides (phasiques)","La quantité d'étirement","La tension tendineuse","La température"],"r":0,"e":"Les récepteurs primaires entourent la région centrale de toutes les fibres intrafusales.","s":1},{"q":"Que renseignent les fibres afférentes II ?","o":["La quantité d'étirement, étant sensibles aux étirements lents et maintenus","La vitesse de l'étirement","La force de contraction","La douleur"],"r":0,"e":"Les récepteurs secondaires entourent majoritairement les fibres à chaîne.","s":1},{"q":"Où se terminent les motoneurones gamma dynamiques ?","o":["Aux extrémités des fibres à sac","Aux extrémités des fibres à chaîne","Sur les fibres extrafusales","Sur l'OTG"],"r":0,"e":"Les Mnγ statiques se terminent aux extrémités des fibres à chaîne et à sac.","s":1},{"q":"Que provoque l'activation du motoneurone gamma ?","o":["La contraction des extrémités du FNM, qui étire sa portion centrale et régule sa sensibilité","La contraction des fibres extrafusales","Le relâchement du muscle","L'inhibition des fibres Ia"],"r":0,"e":"Le FNM reste ainsi sensible même pendant la contraction musculaire.","s":1},{"q":"Qu'est-ce que la co-activation alpha-gamma ?","o":["L'activation simultanée des Mnα et des Mnγ par les voies motrices descendantes pendant les mouvements volontaires","L'inhibition réciproque des antagonistes","La stimulation de l'OTG par la contraction","La sommation des afférences Ia et II"],"r":0,"e":"Elle maintient les FNM actifs et sensibles pendant la contraction.","s":1},{"q":"Comment définit-on le réflexe myotatique ?","o":["La tendance à la contraction d'un muscle après un étirement passif rapide","Le relâchement d'un muscle fortement contracté","L'inhibition des antagonistes","La contraction volontaire"],"r":0,"e":"L'information est conduite par les fibres Ia jusqu'au Mnα du muscle allongé.","s":1},{"q":"Qu'est-ce que l'innervation réciproque dans le réflexe myotatique ?","o":["Les fibres afférentes agissent de façon inhibitrice sur les Mnα des muscles antagonistes","Elles facilitent les antagonistes","Elles inhibent les agonistes","Elles n'ont aucun effet controlatéral"],"r":0,"e":"Le réflexe myotatique contracte le muscle étiré tout en inhibant ses antagonistes.","s":1},{"q":"Dans quels muscles les FNM sont-ils abondants ?","o":["Les muscles à prédominance de fibres toniques lentes de type I : antigravitaires du rachis et des MI, muscles du cou, intrinsèques de la main","Les muscles à fibres rapides de type IIb","Les muscles du membre supérieur uniquement","Le diaphragme uniquement"],"r":0,"e":"Les fibres de type I ont un faible diamètre, sont rouges et résistent bien à la fatigue.","s":1},{"q":"Quelles caractéristiques ont les fibres de type IIb ?","o":["Plus grand diamètre, blanches, moindre tolérance à la fatigue, grande quantité de fibres par Mnα","Faible diamètre et rouges","Grande tolérance à la fatigue","Faible quantité de fibres par Mnα"],"r":0,"e":"Les muscles à prédominance de ces fibres ont beaucoup moins de FNM.","s":1},{"q":"Où se situe l'organe tendineux de Golgi ?","o":["À la jonction myotendineuse","En parallèle des fibres musculaires","Dans la capsule articulaire","Dans le derme"],"r":0,"e":"Il est sensible aux variations de tension du tendon.","s":1},{"q":"À quoi l'OTG réagit-il le plus ?","o":["À la contraction active du muscle","À l'allongement passif seul","À la température","À la vibration"],"r":0,"e":"Il réagit aussi à l'allongement passif, mais surtout à la contraction active.","s":1},{"q":"Par quelles fibres passe le réflexe myotatique inverse ?","o":["Les fibres Ib, via un interneurone inhibiteur","Les fibres Ia, directement sur le Mnα","Les fibres II","Les fibres C"],"r":0,"e":"Il produit l'inhibition des Mnα et le relâchement du muscle contracté.","s":1},{"q":"Quelle voie ascendante transporte la proprioception CONSCIENTE ?","o":["La voie dorsale, qui croise dans le tronc cérébral","La voie antéro-latérale, qui croise à chaque niveau","Les voies spino-cérébelleuses","Le faisceau tecto-spinal"],"r":0,"e":"La voie dorsale transporte aussi le toucher discriminatif jusqu'au cortex controlatéral.","s":1},{"q":"Quelle particularité ont les voies spino-cérébelleuses ?","o":["Elles transportent la proprioception inconsciente jusqu'au cortex cérébelleux du même côté","Elles croisent une seule fois","Elles se projettent sur le cortex controlatéral","Elles transportent la douleur"],"r":0,"e":"La voie antérieure croise puis croise à nouveau en atteignant le cervelet, restant homolatérale.","s":1},{"q":"Le champ sensitif se définit comme :","o":["La zone innervée par un seul neurone sensitif","L'ensemble des récepteurs d'un membre","Le territoire d'un nerf périphérique","La surface d'un dermatome"],"r":0,"e":"Il est plus petit en distal et plus grand en proximal : les zones distales ont une densité de récepteurs supérieure, d'où une meilleure discrimination.","s":1},{"q":"Les récepteurs cutanés contribuent à la notion de position articulaire et de mouvement :","o":["En tant que principaux responsables de la proprioception","Sans en être responsables, mais en y contribuant","Uniquement au repos","Uniquement en charge"],"r":1,"e":"Le contact de la main avec une surface augmente l'input sensoriel et influence le contrôle postural, renforçant le schéma corporel et l'orientation posturale.","s":1},{"q":"Les récepteurs articulaires déchargent à leur fréquence maximale :","o":["En position neutre","Aux angles extrêmes","À mi-course","Au repos"],"r":1,"e":"Ils envoient de l'information à tout angle, mais c'est en fin d'amplitude que leur décharge culmine — d'où leur rôle protecteur.","s":1},{"q":"L'effet réflexe des récepteurs articulaires consiste en :","o":["Une facilitation des agonistes","Une inhibition réflexe des agonistes et une facilitation des antagonistes","Une inhibition de tous les muscles","Une contraction généralisée"],"r":1,"e":"Le cours précise qu'ils sont moins importants qu'on ne le pensait auparavant dans la proprioception, au profit des fuseaux neuromusculaires.","s":1},{"q":"Un fuseau neuromusculaire contient environ :","o":["2 fibres intrafusales","12 fibres intrafusales","50 fibres intrafusales","100 fibres intrafusales"],"r":1,"e":"Il est composé de fibres musculaires intrafusales, de fibres afférentes sensitives et de fibres efférentes motrices.","s":1},{"q":"Les fibres intrafusales à sac sont plus sensibles :","o":["À l'étirement rapide","À l'étirement prolongé et maintenu","À la contraction","À la température"],"r":0,"e":"Les fibres à chaîne sont plus sensibles à l'étirement prolongé et maintenu. Cette double population permet de coder à la fois vitesse et amplitude.","s":1},{"q":"La portion centrale des fibres intrafusales :","o":["Est contractile","N'a pas de capacité de contraction","Contient les motoneurones gamma","Est insensible à l'étirement"],"r":1,"e":"Seules les extrémités sont contractiles. C'est l'organisation des noyaux dans la portion centrale qui différencie fibres à sac et fibres à chaîne.","s":1},{"q":"Les fibres afférentes Ia informent surtout sur :","o":["La quantité d'étirement","La vitesse de l'étirement","La force de contraction","La température"],"r":1,"e":"Elles entourent la région centrale de toutes les fibres intrafusales. Les fibres II, qui entourent majoritairement les fibres à chaîne, informent sur la quantité d'étirement.","s":1},{"q":"Les motoneurones gamma dynamiques se terminent :","o":["Aux extrémités des fibres à sac","Aux extrémités des fibres à chaîne uniquement","Sur les fibres extrafusales","Sur l'organe tendineux de Golgi"],"r":0,"e":"Les motoneurones gamma statiques se terminent aux extrémités des fibres à chaîne et à sac.","s":1},{"q":"La co-activation alpha-gamma a pour effet de :","o":["Rendre le fuseau inactif pendant la contraction","Maintenir le fuseau sensible quel que soit l'état du muscle, par étirement actif de sa portion centrale","Bloquer le réflexe myotatique","Relâcher les fibres intrafusales"],"r":1,"e":"Sans elle, le raccourcissement du muscle détendrait le fuseau, qui cesserait d'informer précisément au moment où le mouvement se produit.","s":1},{"q":"Dans le réflexe myotatique, l'information est conduite à la moelle par :","o":["Les fibres II","Les fibres afférentes rapides Ia","Les fibres Ib","Les fibres C"],"r":1,"e":"Elles se terminent directement sur le motoneurone alpha du muscle étiré, ce qui en fait un réflexe monosynaptique et donc très rapide.","s":1},{"q":"L'innervation réciproque du réflexe myotatique signifie que les fibres afférentes :","o":["Activent aussi les antagonistes","Agissent de façon inhibitrice sur les motoneurones alpha des muscles antagonistes","N'ont aucun effet sur les antagonistes","Inhibent le muscle étiré"],"r":1,"e":"Contracter un muscle tout en relâchant son antagoniste est la condition d'un mouvement efficace : le circuit médullaire l'assure automatiquement.","s":1},{"q":"Les fuseaux neuromusculaires sont abondants dans les muscles :","o":["À prédominance de fibres rapides de type IIb","À prédominance de fibres toniques lentes de type I","Sans prédominance particulière","Uniquement des membres supérieurs"],"r":1,"e":"Les fibres de type I sont de faible diamètre, rouges, très tolérantes à la fatigue — profil des muscles posturaux, où le contrôle fin de la longueur importe le plus.","s":1},{"q":"L'organe tendineux de Golgi réagit le plus :","o":["À l'étirement passif","À la contraction musculaire","À la température","À la pression cutanée"],"r":1,"e":"Situé à la jonction musculo-tendineuse, il informe sur la tension développée, là où le fuseau informe sur la longueur et sa vitesse de variation.","s":1},{"q":"Le réflexe myotatique inverse passe par les fibres :","o":["Ia","II","Ib","IV"],"r":2,"e":"Les fibres Ib véhiculent l'information de l'organe tendineux de Golgi et aboutissent à une inhibition du muscle qui développe une tension excessive.","s":1},{"q":"La proprioception consciente est transportée par :","o":["Les voies spino-cérébelleuses","Les voies des colonnes dorsales et du lemnisque médian","La voie spino-thalamique latérale","La voie tecto-spinale"],"r":1,"e":"Les voies spino-cérébelleuses véhiculent, elles, la proprioception inconsciente, destinée au cervelet.","s":1},{"q":"La particularité des voies spino-cérébelleuses est :","o":["De ne pas atteindre la conscience et de renseigner le cervelet sur l'état du mouvement en cours","D'être les plus lentes","De croiser deux fois","De ne transporter que la douleur"],"r":0,"e":"Elles fournissent au spinocervelet le « résultat » du mouvement, qu'il compare à l'« intention » venue du cortex.","s":1},{"q":"Les trois inputs sensoriels qui ajustent la réponse du système nerveux central au contrôle postural sont :","o":["Somatosensoriel, visuel et vestibulaire","Tactile, thermique et douloureux","Musculaire, articulaire et cutané","Visuel, auditif et olfactif"],"r":0,"e":"Leur redondance permet la compensation : la perte d'un canal peut être partiellement suppléée par les deux autres, principe majeur en rééducation de l'équilibre.","s":1},{"q":"Le schéma corporel désigne :","o":["L'apparence physique perçue","La représentation interne du corps, de sa position et de ses segments, construite à partir des afférences","Le poids corporel","L'image dans le miroir"],"r":1,"e":"Le cours souligne que le contact de la main avec une surface le renforce, ce qui explique l'effet stabilisateur d'un appui même très léger.","s":1},{"q":"Les mécanorécepteurs articulaires se situent notamment :","o":["Dans la capsule articulaire, la synoviale et les ligaments","Dans le cartilage","Dans l'os sous-chondral","Dans le tendon uniquement"],"r":0,"e":"Ils s'accompagnent de terminaisons libres et informent sur l'état de l'articulation, la position, le mouvement et la douleur.","s":1},{"q":"Que nous apporte principalement le système visuel dans le contrôle moteur ?","o":["De l'information sur l'environnement et sur notre localisation dans l'espace, presque instantanément","La force musculaire","La perception de la douleur","Le tonus postural de base"],"r":0,"e":"Il informe aussi sur la localisation, la taille, la forme, la texture et le poids d'un objet.","s":2},{"q":"Quel mécanisme la vision permet-elle dans la locomotion ?","o":["Des mécanismes de feed-forward, avec ajustements anticipatoires des schémas de locomotion","Uniquement des corrections rétroactives","Des réflexes médullaires","La régulation du tonus par les FNM"],"r":0,"e":"Elle permet d'interpréter et d'utiliser l'information de façon prédictive.","s":2},{"q":"Quelles cellules de la rétine convertissent la lumière en input nerveux ?","o":["Les cônes et les bâtonnets","Les cellules ganglionnaires uniquement","Les cellules de Müller","Les otolithes"],"r":0,"e":"L'information est traitée dans la rétine puis transmise au nerf optique.","s":2},{"q":"Que se passe-t-il au chiasma optique ?","o":["Les moitiés internes de chaque nerf croisent vers le côté opposé et s'unissent à la moitié externe du nerf controlatéral","Tous les axones croisent","Aucun axone ne croise","Seules les moitiés externes croisent"],"r":0,"e":"L'information rejoint ensuite le thalamus puis le cortex.","s":2},{"q":"Où est transmise l'information d'un hémichamp visuel ?","o":["Au cortex opposé","Au cortex du même côté","Aux deux cortex de façon égale","Au cervelet uniquement"],"r":0,"e":"Chaque hémisphère reçoit l'information des deux yeux, relative à un champ visuel.","s":2},{"q":"Que discrimine le cortex visuel primaire ?","o":["La texture, la forme et la taille des objets","Les couleurs et le mouvement","La position dans l'espace","La reconnaissance des visages"],"r":0,"e":"Le cortex d'association visuelle discrimine les couleurs et le mouvement.","s":2},{"q":"Quel est le rôle de la voie visuelle dorsale ?","o":["L'ACTION : identifier position, structure et orientation de l'objet pour influencer l'action motrice","La PERCEPTION et la reconnaissance de l'objet","La discrimination des couleurs","Le réflexe vestibulo-oculaire"],"r":0,"e":"Elle va du cortex visuel vers le pariétal ; la voie ventrale va vers le temporal.","s":2},{"q":"Vers quel lobe se dirige la voie visuelle ventrale ?","o":["Le lobe temporal","Le lobe pariétal","Le lobe frontal","Le cervelet"],"r":0,"e":"Elle assure la perception : reconnaissance de l'objet et perception visuelle consciente.","s":2},{"q":"Quel rôle moteur joue le colliculus supérieur ?","o":["Il participe à l'activation de la musculature posturale du cou et coordonne les mouvements d'orientation yeux ↔ tête","Il commande la marche","Il régule le tonus des membres inférieurs","Il traite la douleur"],"r":0,"e":"Il transmet l'information par le faisceau longitudinal et la voie tecto-spinale.","s":2},{"q":"À quels noyaux le faisceau longitudinal transmet-il l'information ?","o":["Aux noyaux des nerfs crâniens III, IV et VI","Aux noyaux vestibulaires","Aux noyaux gris centraux","Au noyau rouge"],"r":0,"e":"Il active ainsi les muscles des yeux en réponse au stimulus visuel.","s":2},{"q":"Quelle est la cible de la voie tecto-spinale ?","o":["La moelle épinière cervicale, pour activer les muscles du cou responsables de la rotation de la tête","Les muscles oculomoteurs","Les muscles des membres inférieurs","Le diaphragme"],"r":0,"e":"Elle prend origine dans le colliculus supérieur et croise vers le côté opposé.","s":2},{"q":"Combien de muscles extra-oculaires possède chaque œil ?","o":["6 : 4 droits et 2 obliques","4 : 2 droits et 2 obliques","8","2"],"r":0,"e":"Les droits sont supérieur, inférieur, interne et externe.","s":2},{"q":"Quelle fonction inconsciente la vision exerce-t-elle ?","o":["Un effet postural sur la musculature du cou et la relation regard ↔ tête ↔ tronc","La relation regard-main","L'orientation visuelle consciente","Les ajustements anticipatoires conscients"],"r":0,"e":"Les fonctions conscientes comprennent le feed-forward et la relation regard-main.","s":2},{"q":"Quelles conséquences peut avoir une altération visuelle sur le mouvement ?","o":["Des illusions perceptives importantes avec stratégies posturales compensatoires et un trouble de la coordination regard-tête-tronc","Une paralysie des membres","Une perte de sensibilité cutanée","Une aréflexie"],"r":0,"e":"Elle influence la pré-planification et le contrôle instantané du mouvement.","s":2},{"q":"À quels deux types d'information le système vestibulaire est-il sensible ?","o":["La position de la tête et du corps dans l'espace, et les changements de direction du mouvement","La température et la douleur","La longueur et la tension musculaires","La couleur et la forme"],"r":0,"e":"C'est un gravirécepteur, important pour l'activité anti-gravitaire et la stabilité oculaire.","s":2},{"q":"Sur quoi les canaux semi-circulaires renseignent-ils ?","o":["Le mouvement angulaire de la tête","L'accélération linéaire","La position par rapport à la pesanteur","La vision périphérique"],"r":0,"e":"L'utricule et le saccule renseignent sur la position par rapport à la pesanteur et l'accélération linéaire.","s":2},{"q":"Comment fonctionnent les canaux semi-circulaires par paires ?","o":["Les deux horizontaux fonctionnent ensemble ; le canal antérieur fonctionne avec le postérieur du côté opposé","Chaque canal fonctionne seul","Les trois canaux d'un même côté fonctionnent ensemble","Les antérieurs fonctionnent entre eux"],"r":0,"e":"Au moins une paire est affectée par toute accélération angulaire.","s":2},{"q":"Où se situent les terminaisons sensorielles des canaux semi-circulaires ?","o":["Dans l'ampoule, partie large terminale où se trouvent les cils vestibulaires","Dans la macule","Dans l'endolymphe","Dans le nerf vestibulaire"],"r":0,"e":"L'utricule et le saccule contiennent quant à eux une macule.","s":2},{"q":"Que se passe-t-il lorsque la tête commence à bouger dans un canal semi-circulaire ?","o":["L'endolymphe ne bouge pas initialement et les cils s'inclinent dans la direction opposée au mouvement","Les cils s'inclinent dans le sens du mouvement","Les otolithes se déplacent","Rien ne se produit"],"r":0,"e":"Quand la tête s'arrête, les cils s'inclinent à nouveau dans la direction opposée.","s":2},{"q":"Quelle est l'orientation de la macule de l'utricule ?","o":["Horizontale","Verticale","Oblique","Variable"],"r":0,"e":"La macule du saccule est verticale.","s":2},{"q":"Que sont les otolithes ?","o":["De petits cristaux lourds situés au sommet de la substance gélatineuse enveloppant les cils de la macule","Des cellules ciliées","Des terminaisons nerveuses","Des canaux membraneux"],"r":0,"e":"Leur poids déplace la masse gélatineuse lorsque la tête change de position.","s":2},{"q":"Vers quelles structures se projettent les noyaux vestibulaires ?","o":["Le cortex, le cervelet, les paires crâniennes oculo-motrices et la moelle épinière","Uniquement le cervelet","Uniquement le cortex","Uniquement la moelle épinière"],"r":0,"e":"L'information leur parvient par le nerf vestibulaire.","s":2},{"q":"À quoi sert principalement l'information des canaux semi-circulaires ?","o":["À stabiliser la vision, par le réflexe vestibulo-oculaire","À activer les muscles antigravitaires","À percevoir la pesanteur","À coordonner la marche"],"r":0,"e":"L'information de l'utricule et du saccule affecte surtout la moelle épinière.","s":2},{"q":"Comment fonctionne le réflexe vestibulo-oculaire ?","o":["Les yeux se déplacent dans le sens opposé au mouvement de la tête pour compenser et stabiliser l'image sur la rétine","Les yeux suivent le mouvement de la tête","Les yeux se ferment","La tête compense le mouvement des yeux"],"r":0,"e":"Il est vertical et horizontal.","s":2},{"q":"Vers quoi se projette majoritairement l'information de l'utricule et du saccule ?","o":["Vers la moelle épinière, activant les motoneurones des muscles posturaux et antigravitaires","Vers les muscles oculomoteurs","Vers le cortex visuel","Vers le colliculus supérieur"],"r":0,"e":"Ce sont les voies vestibulo-spinales.","s":2},{"q":"Quelle est la particularité de la voie vestibulo-spinale latérale ?","o":["Elle est homolatérale, s'étend tout au long de la moelle et facilite les Mn antigravitaires du cou, du tronc et des membres","Elle est bilatérale et limitée au cervical et au thoracique","Elle stabilise la tête par rapport au tronc","Elle innerve les muscles oculomoteurs"],"r":0,"e":"Elle est plus active en position debout et réagit très rapidement pour restaurer l'équilibre.","s":2},{"q":"Quelle est la fonction de la voie vestibulo-spinale médiale ?","o":["Stabiliser la tête par rapport au tronc, avec un rôle important dans la coordination yeux-tête","Faciliter les muscles antigravitaires des membres inférieurs","Restaurer l'équilibre en position debout","Activer les muscles oculomoteurs directement"],"r":0,"e":"Elle se projette bilatéralement vers les niveaux cervicaux et thoraciques.","s":2},{"q":"Quelles fonctions autonomes peuvent être perturbées par une lésion vestibulaire ?","o":["Les nausées et les vomissements","La digestion uniquement","La thermorégulation","La sudation"],"r":0,"e":"On retient aussi le contrôle postural, l'orientation de la tête et les mouvements réflexes des yeux.","s":2},{"q":"Quel est le rôle du thalamus dans le traitement sensoriel ?","o":["C'est un filtre sélectif pour le cortex, recevant l'input des systèmes sensoriels, du cervelet et des noyaux gris centraux","Il génère les réponses motrices réflexes","Il coordonne le mouvement","Il produit le schéma corporel"],"r":0,"e":"Il envoie ces informations vers des localisations spécifiques du cortex.","s":2},{"q":"Que réalise l'aire d'association pariéto-temporale ?","o":["L'intégration de différentes modalités sensorielles, le schéma corporel, les relations spatiales et l'attention dirigée","La génération de réponses motrices","La discrimination des couleurs","Le réflexe vestibulo-oculaire"],"r":0,"e":"Le tronc cérébral génère les réponses motrices, le cervelet coordonne le mouvement.","s":2},{"q":"Le cortex visuel primaire discrimine :","o":["Les couleurs et le mouvement","La texture, la forme et la taille des objets","La position dans l'espace","La reconnaissance des visages"],"r":1,"e":"Le cortex d'association visuelle prend en charge la discrimination des couleurs et du mouvement.","s":2},{"q":"La voie visuelle dorsale, du cortex visuel vers le pariétal, sert :","o":["À la perception consciente","À l'action : identifier position, structure et orientation de l'objet pour guider le mouvement","À la reconnaissance de l'objet","À la mémoire visuelle"],"r":1,"e":"La voie ventrale, vers le lobe temporal, assure la reconnaissance de l'objet et la perception visuelle consciente.","s":2},{"q":"Le colliculus supérieur participe :","o":["À l'activation de la musculature posturale du cou et à la coordination des mouvements d'orientation yeux-tête","À la discrimination des couleurs","À la mémoire visuelle","À l'accommodation"],"r":0,"e":"C'est un relais sous-cortical du traitement visuel, qui produit des réponses motrices rapides sans passer par le cortex.","s":2},{"q":"Le faisceau longitudinal transmet l'information aux noyaux des nerfs crâniens :","o":["III, IV et VI","V, VII et IX","II et VIII","X, XI et XII"],"r":0,"e":"Ces trois noyaux commandent les muscles extra-oculaires, permettant d'activer les yeux en réponse à un stimulus visuel.","s":2},{"q":"La voie tecto-spinale prend origine dans :","o":["Le cortex visuel","Le colliculus supérieur","Le noyau rouge","Les noyaux vestibulaires"],"r":1,"e":"Elle croise vers le côté opposé et active les motoneurones de la moelle cervicale responsables de la rotation de la tête vers un son ou un stimulus visuel.","s":2},{"q":"Chaque œil possède combien de muscles extra-oculaires ?","o":["4","6","8","12"],"r":1,"e":"Quatre droits — supérieur, inférieur, interne, externe — et deux obliques, supérieur et inférieur.","s":2},{"q":"Parmi les fonctions inconscientes de la vision, le cours cite :","o":["L'orientation visuelle dans l'environnement","L'effet postural de la musculature du cou et la relation regard-tête-tronc","La relation regard-main","Le mécanisme de feed-forward"],"r":1,"e":"Les fonctions conscientes comprennent les ajustements anticipatoires, l'orientation dans l'environnement et la relation regard-main pour la manipulation.","s":2},{"q":"Une altération visuelle peut produire :","o":["Des illusions perceptives importantes, associées à des stratégies posturales compensatoires","Une paralysie oculaire","Une perte de sensibilité cutanée","Une ataxie cérébelleuse"],"r":0,"e":"S'y ajoute un trouble de la coordination regard-tête-tronc. Elle affecte donc à la fois la pré-planification et le contrôle instantané du mouvement.","s":2},{"q":"Le système vestibulaire est qualifié de gravirécepteur parce qu'il renseigne sur :","o":["La température","La position de la tête et du corps dans l'espace et les changements de direction du mouvement","La douleur","La longueur musculaire"],"r":1,"e":"Ses inputs sont essentiels à l'activité anti-gravitaire, à la verticalité et à la stabilité oculaire.","s":2},{"q":"Les canaux semi-circulaires renseignent sur :","o":["Le mouvement angulaire de la tête","L'accélération linéaire","La position par rapport à la pesanteur","La pression artérielle"],"r":0,"e":"L'utricule et le saccule informent, eux, sur la position par rapport à la pesanteur et sur l'accélération ou la décélération linéaire.","s":2},{"q":"Concernant le fonctionnement par paires des canaux semi-circulaires :","o":["Les deux canaux horizontaux fonctionnent ensemble, et le canal antérieur avec le postérieur du côté opposé","Chaque canal fonctionne isolément","Les trois canaux d'un côté fonctionnent ensemble","Les canaux antérieurs fonctionnent entre eux"],"r":0,"e":"Cette organisation garantit qu'au moins une paire est affectée par toute accélération angulaire, quel que soit le plan du mouvement.","s":2},{"q":"Les terminaisons sensorielles des canaux semi-circulaires se situent :","o":["Dans le canal lui-même","Dans l'ampoule, partie large terminale où se trouvent les cils vestibulaires","Dans l'utricule","Dans le nerf vestibulaire"],"r":1,"e":"C'est l'inertie de l'endolymphe qui, au démarrage du mouvement, incline les cils dans la direction opposée à celle de la tête.","s":2},{"q":"Lorsque la tête s'arrête après une rotation, les cils vestibulaires :","o":["Reviennent immédiatement en position neutre","S'inclinent à nouveau, dans la direction vers laquelle la tête s'était initialement déplacée","Restent immobiles","S'inclinent dans la même direction qu'au départ"],"r":1,"e":"C'est l'inertie de l'endolymphe qui continue son mouvement : ce phénomène explique la sensation de rotation persistante après un arrêt brusque.","s":2},{"q":"La macule de l'utricule est orientée :","o":["Horizontalement","Verticalement","Obliquement","De façon variable"],"r":0,"e":"Celle du saccule est verticale. Cette orthogonalité permet de coder les accélérations linéaires dans tous les plans.","s":2},{"q":"Les otolithes sont :","o":["Des cils vestibulaires","Des cristaux petits et lourds situés au sommet de la masse gélatineuse recouvrant la macule","Des récepteurs articulaires","Des cellules nerveuses"],"r":1,"e":"Leur masse est ce qui rend le système sensible à la gravité : un changement de position de la tête déplace la masse gélatineuse et incline les cils.","s":2},{"q":"L'information des canaux semi-circulaires sert principalement :","o":["Au réflexe vestibulo-oculaire et à la stabilisation du regard","Au contrôle postural du tronc","À la perception de la verticale","À la locomotion"],"r":0,"e":"L'information de l'utricule et du saccule se projette majoritairement vers les voies vestibulo-spinales, pour le contrôle postural.","s":2},{"q":"Le réflexe vestibulo-oculaire fonctionne en :","o":["Fixant les yeux dans l'orbite","Produisant un mouvement oculaire égal et opposé à celui de la tête, ce qui stabilise l'image sur la rétine","Fermant les paupières","Dilatant la pupille"],"r":1,"e":"C'est ce qui permet de garder un texte lisible en marchant : sans lui, chaque pas ferait osciller l'image.","s":2},{"q":"Les noyaux vestibulaires se projettent notamment vers :","o":["Le cervelet, la moelle épinière et les noyaux oculomoteurs","Le cortex visuel primaire uniquement","Les noyaux gris centraux","La substance noire"],"r":0,"e":"Cette triple projection explique les trois fonctions du système : coordination cérébelleuse, contrôle postural et stabilisation du regard.","s":2},{"q":"Dans la locomotion, la vision permet notamment :","o":["Un mécanisme d'anticipation, en informant sur l'environnement avant que le pied ne se pose","La contraction réflexe des extenseurs","La perception de la douleur","Le contrôle de la respiration"],"r":0,"e":"C'est un exemple typique de feedforward : l'information visuelle prépare l'ajustement avant même que le contact ne se produise.","s":2},{"q":"Les cellules de la rétine qui convertissent la lumière en influx nerveux sont :","o":["Les cellules ganglionnaires","Les photorécepteurs, cônes et bâtonnets","Les cellules bipolaires","Les cellules amacrines"],"r":1,"e":"L'information gagne ensuite le chiasma optique, où les fibres nasales croisent, de sorte que chaque hémisphère reçoit tout un hémichamp visuel.","s":2},{"q":"Quelle scissure sépare le lobe frontal du lobe pariétal ?","o":["La scissure de Rolando (centrale)","La scissure de Sylvius","La scissure perpendiculaire externe","La scissure inter-hémisphérique"],"r":0,"e":"La scissure de Sylvius est la scissure latérale.","s":3},{"q":"Combien d'aires Brodmann a-t-il distinguées en 1909 ?","o":["52","32","12","100"],"r":0,"e":"Il s'est fondé sur les caractéristiques histologiques et fonctionnelles.","s":3},{"q":"Quelle est la fonction générale du lobe pariétal ?","o":["Réception et évaluation de l'information somatosensorielle","Fonction motrice volontaire","Intégration des stimuli visuels","Évaluation des stimuli olfactifs et auditifs"],"r":0,"e":"Le lobe frontal assure la fonction motrice volontaire, la motivation, la personnalité et l'humeur.","s":3},{"q":"Quel lobe joue un rôle important dans la mémoire et reçoit les stimuli olfactifs et auditifs ?","o":["Le lobe temporal","Le lobe occipital","Le lobe pariétal","Le lobe limbique"],"r":0,"e":"Le lobe limbique gère les instincts de survie de base.","s":3},{"q":"Quelles sont les cinq divisions fonctionnelles du cortex ?","o":["Sensoriel primaire, association sensorielle, planification motrice, moteur primaire et association","Frontal, pariétal, temporal, occipital, limbique","Primaire, secondaire, tertiaire, associatif, limbique","Moteur, sensoriel, cognitif, émotionnel, végétatif"],"r":0,"e":"Chacune assure une fonction spécifique dans le contrôle moteur.","s":3},{"q":"D'où les aires sensorielles primaires reçoivent-elles l'information ?","o":["Directement des noyaux thalamiques","Du cervelet","Des noyaux gris centraux","De la moelle épinière"],"r":0,"e":"Il existe une aire primaire pour chaque type de sensation.","s":3},{"q":"Quelle est la conséquence d'une lésion des aires sensorielles primaires ?","o":["Une diminution de la capacité à discriminer l'intensité et la qualité des stimuli","Une agnosie","Une aphasie de Wernicke","Une négligence"],"r":0,"e":"Elle interfère sévèrement avec la capacité à utiliser les sensations.","s":3},{"q":"Qu'est-ce que l'agnosie ?","o":["L'incapacité à reconnaître des objets à partir d'un sens spécifique, malgré l'intégrité de ce sens","Une perte de sensibilité","Un trouble du langage","Une négligence spatiale"],"r":0,"e":"C'est la principale conséquence d'une lésion des aires d'association sensorielle.","s":3},{"q":"Dans l'exemple du stylo, que fait le cortex d'association somatosensorielle ?","o":["Il reconnaît l'objet comme étant un stylo","Il perçoit qu'il est petit et cylindrique","Il commande la préhension","Il localise l'objet dans l'espace"],"r":0,"e":"Le cortex somatosensoriel primaire perçoit qu'il est petit et cylindrique.","s":3},{"q":"Quels sont les inputs des trois aires motrices ?","o":["Les aires sensorielles, le cervelet et les noyaux gris centraux","La moelle épinière uniquement","Le thalamus uniquement","Le système limbique"],"r":0,"e":"Leur output va vers la moelle épinière, les noyaux du tronc cérébral et le cervelet.","s":3},{"q":"Quelle aire planifie le mouvement à partir de l'information externe, principalement visuelle ?","o":["L'aire prémotrice (aire 6 latérale)","L'aire motrice supplémentaire (aire 6 interne)","Le cortex moteur primaire","L'aire de Broca"],"r":0,"e":"C'est le mouvement guidé de l'extérieur (externally guided movement).","s":3},{"q":"Quels sont les inputs de l'aire prémotrice ?","o":["Le cortex pariétal et le cervelet","Le cortex pariétal et les noyaux gris centraux","Le thalamus seul","La moelle épinière"],"r":0,"e":"L'aire motrice supplémentaire reçoit le cortex pariétal et les noyaux gris centraux.","s":3},{"q":"Quelle aire est liée à l'activation de séquences de mouvement (programmes moteurs) ?","o":["L'aire motrice supplémentaire","L'aire prémotrice","Le cortex moteur primaire","L'aire préfrontale"],"r":0,"e":"Elle planifie le mouvement à partir de l'information interne (mémoire).","s":3},{"q":"À quoi l'aire prémotrice est-elle liée sur le plan fonctionnel ?","o":["À la fonction de la main : atteindre et saisir, et à l'apprentissage associatif","Aux séquences de mouvement mémorisées","Au contrôle postural axial","Au langage"],"r":0,"e":"Son apprentissage moteur est conditionné par l'information sensorielle.","s":3},{"q":"Quelle est la particularité du cortex moteur primaire ?","o":["C'est la seule aire du cortex moteur qui communique directement avec les neurones moteurs de la moelle épinière","C'est la seule à recevoir le thalamus","C'est la seule à planifier le mouvement","C'est la seule à croiser la ligne médiane"],"r":0,"e":"Il contrôle les mouvements volontaires, surtout fractionnés et fins.","s":3},{"q":"Quelles régions occupent le plus de place dans la carte du cortex moteur primaire ?","o":["Celles nécessitant un contrôle moteur fin, comme la main et la face","Le tronc","Les membres inférieurs","Le bassin"],"r":0,"e":"La représentation est disproportionnée en faveur des régions à motricité fine.","s":3},{"q":"Comment définit-on la voie cortico-spinale ?","o":["Toutes les fibres qui partent du cortex, descendent et innervent des neurones médullaires sans interruption synaptique","Les fibres qui relient le cortex au cervelet","Les voies ascendantes sensorielles","Les fibres commissurales"],"r":0,"e":"Elle active principalement la musculature distale.","s":3},{"q":"Quelle proportion de la voie cortico-spinale provient des aires motrices ?","o":["Environ 70 %","Environ 30 %","Environ 50 %","Environ 90 %"],"r":0,"e":"Environ 30 % proviennent des aires sensorielles.","s":3},{"q":"Quelle proportion des fibres cortico-spinales croise aux pyramides bulbaires ?","o":["Environ 3/4","Environ 1/4","La totalité","Aucune"],"r":0,"e":"Le quart restant forme la voie cortico-spinale médiale, qui ne croise pas.","s":3},{"q":"Dans quel cordon descend la voie cortico-spinale médiale ?","o":["Le cordon antérieur","Le cordon latéral","Le cordon postérieur","Le faisceau gracile"],"r":0,"e":"La voie latérale descend dans le cordon latéral.","s":3},{"q":"À quels niveaux la voie cortico-spinale médiale fait-elle synapse ?","o":["Aux niveaux cervical et thoracique","Tout au long de la moelle","Au niveau lombaire uniquement","Au niveau sacré"],"r":0,"e":"Elle porte l'information aux Mn qui contrôlent le cou, les épaules et le tronc.","s":3},{"q":"Quelle est la fonction principale de la voie cortico-spinale médiale ?","o":["Le contrôle de la posture et des mouvements proximaux, avec les ajustements posturaux anticipatoires","Le fractionnement du mouvement des mains","La régulation des réflexes médullaires","La transmission de la douleur"],"r":0,"e":"Elle agit avec les voies vestibulo-spinales, tecto-spinale et réticulo-spinale médiale.","s":3},{"q":"Quelle est la fonction principale de la voie cortico-spinale latérale ?","o":["La capacité à fractionner le mouvement des membres, surtout des mains, et à activer des muscles individuels","Le contrôle postural axial","Les ajustements posturaux anticipatoires","La stabilisation de la tête"],"r":0,"e":"Elle provient majoritairement du cortex moteur primaire et ses fibres croisent.","s":3},{"q":"Où se terminent les axones cortico-spinaux issus des aires sensorielles ?","o":["Majoritairement dans la corne postérieure de la moelle (lames I-VI)","Dans la corne antérieure","Dans le cervelet","Dans le thalamus"],"r":0,"e":"Ils font synapse avec des interneurones recevant l'input des récepteurs somatosensoriels.","s":3},{"q":"Qu'est-ce que l'inhibition pré-synaptique du système cortico-spinal ?","o":["La modulation voire l'inhibition des influx excitateurs périphériques qui déstabiliseraient le fonctionnement du SNC","L'inhibition des motoneurones alpha","L'inhibition des antagonistes","Le blocage des voies ascendantes"],"r":0,"e":"Elle participe au contrôle des réflexes médullaires.","s":3},{"q":"Où se terminent les voies cortico-spinales indirectes ?","o":["Dans le tronc cérébral","Dans la moelle épinière","Dans le cervelet","Dans le thalamus"],"r":0,"e":"Les voies directes se terminent dans la moelle épinière.","s":3},{"q":"Quelles sont les conséquences d'une lésion de la voie cortico-spinale latérale ?","o":["Parésie controlatérale, perte de la capacité à fractionner le mouvement et hypersensibilité aux stimuli périphériques","Uniquement un déficit postural","Une agnosie","Une aphasie"],"r":0,"e":"La fonction distale est contrôlée exclusivement par les voies cortico-spinales.","s":3},{"q":"Pourquoi une lésion de la voie cortico-spinale médiale a-t-elle des conséquences moins évidentes ?","o":["Parce que l'activité des autres voies posturales persiste","Parce qu'elle ne croise pas","Parce qu'elle est peu volumineuse","Parce qu'elle est purement sensorielle"],"r":0,"e":"Elle affecte principalement l'activité posturale qui précède les mouvements intentionnels.","s":3},{"q":"Quelle est la conséquence d'une lésion de l'aire préfrontale ?","o":["Apathie et absence de comportement dirigé vers l'objectif, avec difficulté des fonctions exécutives","Une agnosie visuelle","Une négligence spatiale","Une aphasie de Wernicke"],"r":0,"e":"Ces patients sont souvent mal interprétés comme démotivés alors qu'ils n'en ont pas la capacité neurale.","s":3},{"q":"Quelle aphasie résulte d'une lésion pariéto-temporale gauche ?","o":["L'aphasie de Wernicke, avec absence de conscience de la dysfonction","L'aphasie de Broca","Une dysarthrie","Une apraxie"],"r":0,"e":"Le patient produit des sons sans signification et est incapable de lire ou d'écrire.","s":3},{"q":"Brodmann a publié en 1909 une carte du cortex distinguant :","o":["12 aires","32 aires","52 aires","104 aires"],"r":2,"e":"Il s'est fondé sur les caractéristiques histologiques et fonctionnelles, établissant une organisation fonctionnelle plutôt qu'anatomique.","s":3},{"q":"Le lobe temporal reçoit et évalue :","o":["Les stimuli visuels","Les stimuli olfactifs et auditifs, et joue un rôle important dans la mémoire","L'information somatosensorielle","Les fonctions motrices"],"r":1,"e":"Le lobe occipital traite le visuel, le pariétal le somatosensoriel, le frontal la motricité volontaire, la motivation, la personnalité et l'humeur.","s":3},{"q":"Le lobe limbique est associé :","o":["Aux instincts de survie de base : mémoire, reproduction, nutrition","À la vision","À la motricité fine","À l'audition"],"r":0,"e":"Sa dénomination souligne sa position de bordure entre les structures corticales et sous-corticales.","s":3},{"q":"Les hémisphères sont divisés en lobes par des scissures dont :","o":["La scissure de Sylvius, la scissure de Rolando et la scissure perpendiculaire externe","La scissure inter-hémisphérique uniquement","Les sillons secondaires","Les circonvolutions"],"r":0,"e":"Les sillons divisent ensuite les lobes en circonvolutions ou gyrus ; la scissure inter-hémisphérique sépare les deux hémisphères.","s":3},{"q":"Le cortex sensoriel primaire reçoit l'information :","o":["Directement des noyaux thalamiques","Du cortex d'association","Des aires motrices","De la moelle épinière directement"],"r":0,"e":"Il existe une aire primaire pour chaque type de sensation — somatosensorielle, visuelle, vestibulaire, auditive — située dans des régions différentes.","s":3},{"q":"Une lésion du cortex sensoriel primaire entraîne :","o":["Une agnosie","Une diminution de la capacité à discriminer l'intensité et la qualité des stimuli","Une paralysie","Une aphasie"],"r":1,"e":"Elle interfère sévèrement avec la capacité à utiliser les sensations. L'agnosie résulte, elle, d'une lésion du cortex d'association sensorielle.","s":3},{"q":"Dans l'exemple du stylo, le cortex d'association somatosensorielle :","o":["Perçoit qu'il est petit et cylindrique","Reconnaît l'objet comme étant un stylo","Commande la préhension","Planifie le mouvement"],"r":1,"e":"Le cortex somatosensoriel primaire perçoit les qualités physiques ; l'aire d'association leur donne un sens en identifiant l'objet.","s":3},{"q":"L'agnosie se définit comme :","o":["Une incapacité à reconnaître des objets à partir d'un sens spécifique, malgré l'intégrité de ce sens","Une perte de sensibilité","Une paralysie d'un membre","Un trouble du langage"],"r":0,"e":"La distinction est essentielle : la sensation est intacte, c'est son interprétation qui fait défaut.","s":3},{"q":"L'aire prémotrice, aire 6 latérale, prend en charge :","o":["Le mouvement généré en interne à partir de la mémoire","Le mouvement guidé par l'information externe, notamment visuelle","Le contrôle postural","La discrimination sensorielle"],"r":1,"e":"L'aire motrice supplémentaire, aire 6 interne, prend en charge le mouvement généré en interne — distinction reprise dans le cours sur les noyaux gris centraux.","s":3},{"q":"La voie cortico-spinale provient à environ :","o":["100 % des aires motrices","70 % des aires motrices et 30 % des aires sensorielles","50 % de chaque","30 % des aires motrices et 70 % des aires sensorielles"],"r":1,"e":"Cette contribution sensorielle importante rappelle que la commande motrice est indissociable du traitement de l'information afférente.","s":3},{"q":"Aux pyramides bulbaires, la proportion de fibres qui croisent est d'environ :","o":["La moitié","Un quart","Trois quarts","La totalité"],"r":2,"e":"Les trois quarts forment la voie cortico-spinale latérale ; le quart restant, qui ne croise pas, constitue la voie médiale.","s":3},{"q":"La voie cortico-spinale latérale est responsable :","o":["De la posture et des mouvements proximaux","Du mouvement fractionné distal","Des ajustements posturaux anticipatoires","Des réflexes"],"r":1,"e":"La voie médiale prend en charge la posture, les mouvements proximaux et les ajustements posturaux anticipatoires.","s":3},{"q":"Une lésion de la voie cortico-spinale latérale provoque :","o":["Une parésie homolatérale","Une parésie controlatérale, une perte de la capacité à fractionner le mouvement et une hypersensibilité aux stimuli périphériques","Une ataxie","Un tremblement de repos"],"r":1,"e":"La perte du mouvement fractionné explique les schémas globaux observés en hémiplégie : le patient ne peut plus dissocier les articulations.","s":3},{"q":"Les aires de planification motrice ont pour fonction :","o":["De discriminer les intensités sensorielles","D'organiser et de planifier les mouvements","De contrôler directement la contraction musculaire","D'interpréter les émotions"],"r":1,"e":"Le cortex moteur primaire assure le contrôle des mouvements volontaires, et le cortex d'association le comportement, l'interprétation sensorielle et les émotions.","s":3},{"q":"Les aires motrices donnent naissance à des projections :","o":["Uniquement directes vers la moelle épinière","Directes vers la moelle épinière et indirectes vers le tronc cérébral","Uniquement vers le cervelet","Uniquement vers le thalamus"],"r":1,"e":"Cette double voie explique qu'une lésion corticale altère à la fois la commande fine distale et les ajustements posturaux relayés par le tronc.","s":3},{"q":"Le lobe frontal est associé, outre la fonction motrice volontaire :","o":["À la motivation, à la personnalité et à l'humeur","À l'audition","À la vision","À la proprioception"],"r":0,"e":"Cette association explique que des lésions frontales puissent modifier profondément le comportement sans toucher la motricité elle-même.","s":3},{"q":"Le cortex d'association sensorielle analyse l'information provenant :","o":["Uniquement du thalamus","Tant du thalamus que des aires sensorielles primaires","Uniquement des aires primaires","Uniquement de la moelle"],"r":1,"e":"C'est cette double entrée qui lui permet de confronter le signal brut à son traitement initial pour lui donner du sens.","s":3},{"q":"Les circonvolutions, ou gyrus, résultent de la division des lobes par :","o":["Les scissures","Les sillons","Les ventricules","Les commissures"],"r":1,"e":"La hiérarchie est la suivante : scissure inter-hémisphérique, puis scissures pour les lobes, puis sillons pour les circonvolutions.","s":3},{"q":"Le cortex d'association a notamment pour rôle :","o":["De discriminer l'intensité des stimuli","De contrôler le comportement, d'interpréter la sensation et de traiter émotions et souvenirs","De commander directement les muscles","De relayer l'information thalamique"],"r":1,"e":"C'est la cinquième des divisions fonctionnelles, aux côtés du cortex sensoriel primaire, de l'association sensorielle, des aires de planification et du cortex moteur primaire.","s":3},{"q":"La scissure de Rolando est également appelée :","o":["Scissure latérale","Scissure centrale","Scissure pariéto-occipitale","Scissure inter-hémisphérique"],"r":1,"e":"La scissure de Sylvius est la scissure latérale, la scissure perpendiculaire externe la scissure pariéto-occipitale.","s":3},{"q":"De quoi le cervelet est-il le grand responsable ?","o":["La coordination du mouvement","La production de la force","La perception de la douleur","La programmation du langage"],"r":0,"e":"Il intervient aussi dans la dextérité fine, l'équilibre, la posture, la planification et l'apprentissage moteur.","s":4},{"q":"Quel rapport existe entre input et output cérébelleux ?","o":["Le cervelet a 40 fois plus d'input que d'output","Autant d'input que d'output","4 fois plus d'input","Plus d'output que d'input"],"r":0,"e":"Sa fonction de coordination repose sur cette grande quantité d'afférences.","s":4},{"q":"D'où proviennent les fibres grimpantes ?","o":["De l'olive bulbaire, dans le tronc cérébral","De la moelle épinière","Du système vestibulaire","Du cortex via les noyaux du pont"],"r":0,"e":"Elles apportent l'information sur les erreurs qui surviennent dans le mouvement.","s":4},{"q":"Quelle information les fibres grimpantes transportent-elles ?","o":["L'information sur les erreurs qui surviennent dans le mouvement","L'information somatosensorielle","L'information vestibulaire","L'information sur l'état d'alerte"],"r":0,"e":"Elles proviennent de l'olive bulbaire.","s":4},{"q":"Quelle information la substance réticulée envoie-t-elle au cervelet ?","o":["L'information sur l'état d'alerte","L'information somatosensorielle","L'information visuelle","L'information sur les erreurs"],"r":0,"e":"Elle passe par les fibres moussues.","s":4},{"q":"Par où passe l'information corticale avant d'atteindre le cervelet ?","o":["Par les noyaux du pont","Par l'olive bulbaire","Par le thalamus","Par le noyau rouge"],"r":0,"e":"Ce sont des fibres moussues apportant l'information motrice.","s":4},{"q":"Quelles cellules constituent les efférences du cortex cérébelleux ?","o":["Les cellules de Purkinje","Les cellules granulaires","Les fibres moussues","Les fibres grimpantes"],"r":0,"e":"Elles communiquent l'information aux noyaux du cervelet.","s":4},{"q":"Vers quelles structures se projettent les noyaux du cervelet ?","o":["Noyaux vestibulaires, noyaux de la substance réticulée, noyau rouge et cortex via le thalamus","La moelle épinière directement","Les motoneurones alpha","Les récepteurs musculaires"],"r":0,"e":"Ils influencent ainsi les voies vestibulo-spinale, réticulo-spinale, rubro-spinale et cortico-spinale.","s":4},{"q":"Quelle voie descendante le noyau rouge influence-t-il ?","o":["La voie rubro-spinale","La voie vestibulo-spinale","La voie réticulo-spinale","La voie cortico-spinale"],"r":0,"e":"Les noyaux vestibulaires influencent la voie vestibulo-spinale.","s":4},{"q":"Quel est le nom anatomique du vestibulocervelet ?","o":["Le lobe flocculo-nodulaire","Le lobe antérieur","Le vermis","L'hémisphère latéral"],"r":0,"e":"C'est phylogénétiquement la partie la plus ancienne du cervelet.","s":4},{"q":"Quelle est la fonction principale du vestibulocervelet ?","o":["Collaborer au maintien de l'équilibre, au contrôle de la tête et à la coordination yeux-tête","Corriger l'erreur pendant le mouvement","Planifier le mouvement volontaire","Automatiser les séquences motrices"],"r":0,"e":"Son output se dirige vers les noyaux vestibulaires : voies vestibulo-spinales et RVO.","s":4},{"q":"Quelles régions correspondent au spinocervelet ?","o":["Le lobe antérieur et les régions du vermis et du paravermis","Le lobe flocculo-nodulaire","Les hémisphères latéraux","Les noyaux pontiques"],"r":0,"e":"Il reçoit l'intention (cortex) et le résultat (voies spino-cérébelleuses).","s":4},{"q":"Quelles deux informations le spinocervelet compare-t-il ?","o":["L'intention venant du cortex et le résultat venant des voies spino-cérébelleuses","La vision et la proprioception","L'équilibre et la posture","Le timing et la force"],"r":0,"e":"Cette comparaison lui permet de déclencher corrections et ajustements.","s":4},{"q":"Quelles sont les fonctions principales du spinocervelet ?","o":["Correction de l'erreur, coordination instantanée du mouvement et contrôle postural dynamique","Planification et pré-programmation","Coordination yeux-tête","Automatisation des séquences"],"r":0,"e":"Son output influence instantanément les motoneurones supérieurs.","s":4},{"q":"Quelle région correspond au cérébrocervelet ?","o":["Les régions de l'hémisphère latéral","Le lobe flocculo-nodulaire","Le vermis","Le lobe antérieur"],"r":0,"e":"Il reçoit la majorité des fibres du cortex cérébral, via les noyaux pontiques.","s":4},{"q":"Quelles sont les fonctions du cérébrocervelet ?","o":["Planification et pré-programmation motrice, timing d'activation, précision du mouvement volontaire et apprentissage moteur","Correction de l'erreur instantanée","Maintien de l'équilibre","Contrôle du réflexe vestibulo-oculaire"],"r":0,"e":"Son output retourne vers le cortex via le thalamus.","s":4},{"q":"Pourquoi les facteurs du mouvement volontaire sont-ils programmés avant son début ?","o":["Parce que les mouvements volontaires ont une durée courte et qu'il n'y a normalement pas de modification du geste pendant l'exécution","Parce que le cortex est trop lent","Parce que le cervelet est inactif pendant le mouvement","Parce que la moelle prend le relais"],"r":0,"e":"L'intensité relative et la structure spatio-temporelle de la contraction sont préprogrammées.","s":4},{"q":"Quel schéma triphasique le cérébrocervelet contrôle-t-il ?","o":["Préparation, accélération, décélération","Initiation, maintien, arrêt","Excentrique, isométrique, concentrique","Feedback, feedforward, correction"],"r":0,"e":"Il inverse l'activité agoniste/antagoniste au moment adéquat.","s":4},{"q":"Quelle division intervient AVANT la réalisation du mouvement ?","o":["Le cérébro-cervelet","Le spino-cervelet","Le vestibulo-cervelet","Aucune"],"r":0,"e":"Le spino-cervelet intervient pendant la réalisation du mouvement.","s":4},{"q":"Comment définit-on l'ataxie ?","o":["Un mouvement volontaire de force normale, mais inadapté, incoordonné et imprécis, sans rigidité ni hypertonie","Une paralysie des membres","Une hypertonie généralisée","Une perte de sensibilité"],"r":0,"e":"« A-taxie » signifie littéralement absence d'ordre.","s":4},{"q":"Qu'est-ce que la dysmétrie ?","o":["L'incapacité à évaluer avec précision une distance, une direction ou une amplitude de mouvement","Un tremblement au repos","Une difficulté à alterner rapidement les mouvements","Une hypertonie"],"r":0,"e":"Elle aboutit à un mouvement inadapté.","s":4},{"q":"Quand survient le tremblement intentionnel ?","o":["Pendant le mouvement volontaire, principalement au point où une plus grande précision est nécessaire","Au repos","Pendant le sommeil","Uniquement en position debout"],"r":0,"e":"Il est caractéristique des lésions cérébelleuses.","s":4},{"q":"Qu'est-ce que la dysdiadococinésie ?","o":["La difficulté à réaliser des mouvements rapides et alternés, avec incapacité à maintenir un rythme régulier","Une difficulté d'initiation du mouvement","Une décomposition du mouvement","Un tremblement de repos"],"r":0,"e":"Elle inclut aussi l'incapacité à contrôler la force nécessaire.","s":4},{"q":"Qu'est-ce que la décomposition du mouvement ?","o":["La difficulté à réaliser des mouvements complexes impliquant plusieurs articulations, par erreurs de timing et instabilité proximale","Un tremblement d'attitude","Une dysmétrie isolée","Une hypotonie"],"r":0,"e":"L'instabilité proximale ne résiste pas à la force générée en distal.","s":4},{"q":"Quel mécanisme explique les altérations de l'ataxie ?","o":["Un retard à l'allumage et à l'extinction du muscle, avec activité agoniste prolongée et activité antagoniste retardée","Une perte de force","Une hypertonie pyramidale","Une atteinte des fuseaux neuromusculaires"],"r":0,"e":"Toute tentative de correction cause des potentialisations répétées.","s":4},{"q":"Quel signe est caractéristique d'une atteinte du vestibulo-cervelet ?","o":["Le nystagmus et la difficulté de fixation oculaire","La dysarthrie","La dysdiadococinésie","La décomposition du mouvement"],"r":0,"e":"On observe aussi une ataxie du tronc avec troubles de l'équilibre.","s":4},{"q":"Quel signe est caractéristique d'une atteinte du spino-cervelet ?","o":["Difficulté à réaliser des corrections et ajustements posturaux pendant le mouvement, dysmétrie, tremblement intentionnel, dysdiadococinésie et hypotonie","Nystagmus","Dysarthrie","Difficulté des mouvements indépendants des doigts"],"r":0,"e":"Le spino-cervelet corrige et ajuste pendant la réalisation du mouvement.","s":4},{"q":"Quel signe est caractéristique d'une atteinte du cérébro-cervelet ?","o":["Retard à l'initiation, décomposition du mouvement, difficulté des mouvements indépendants des doigts et dysarthrie","Nystagmus","Hypotonie","Troubles de l'équilibre du tronc"],"r":0,"e":"La dysarthrie donne un discours « pâteux » et difficile.","s":4},{"q":"Qu'est-ce que la dysarthrie dans les atteintes cérébelleuses ?","o":["Une difficulté de contrôle des muscles de la bouche et de la parole, avec un discours pâteux et difficile","Une perte de compréhension du langage","Une incapacité à lire","Une aphasie de Broca"],"r":0,"e":"Elle relève d'une atteinte du cérébro-cervelet.","s":4},{"q":"Pourquoi les lésions unilatérales du cervelet ont-elles des conséquences homolatérales ?","o":["Parce que les voies descendantes médianes restent homolatérales et que les efférences vers le cortex controlatéral repassent par des voies qui croisent à nouveau","Parce que le cervelet ne croise jamais","Parce que les efférences sont bilatérales","Parce que le thalamus ne croise pas"],"r":0,"e":"C'est une particularité clinique importante du cervelet.","s":4},{"q":"Le cervelet reçoit combien de fois plus d'input que d'output ?","o":["4 fois","10 fois","40 fois","100 fois"],"r":2,"e":"Ce déséquilibre massif traduit sa fonction : comparer en permanence l'intention au résultat, ce qui exige un flux d'information entrant considérable.","s":4},{"q":"Les fibres grimpantes du cervelet proviennent :","o":["De la moelle épinière","De l'olive bulbaire, et portent l'information sur les erreurs du mouvement","Du système vestibulaire","Du cortex via les noyaux du pont"],"r":1,"e":"Les fibres moussues apportent, elles, l'information somatosensorielle, vestibulaire, l'état d'alerte de la substance réticulée et l'information motrice corticale.","s":4},{"q":"Les fibres moussues issues de la substance réticulée apportent l'information sur :","o":["Les erreurs du mouvement","L'état d'alerte","L'équilibre","La position articulaire"],"r":1,"e":"Le cervelet intègre donc le niveau de vigilance dans sa régulation : la coordination n'est pas la même chez un sujet alerte ou somnolent.","s":4},{"q":"Les fibres efférentes du cortex cérébelleux sont :","o":["Les fibres moussues","Les cellules de Purkinje","Les fibres grimpantes","Les cellules granulaires"],"r":1,"e":"Elles reçoivent l'information des afférences et la communiquent aux noyaux du cervelet, qui constituent la véritable sortie de la structure.","s":4},{"q":"Après traitement cérébelleux, l'information dirigée vers le noyau rouge influence :","o":["La voie vestibulo-spinale","La voie réticulo-spinale","La voie rubro-spinale","La voie cortico-spinale"],"r":2,"e":"Les noyaux vestibulaires commandent la voie vestibulo-spinale, la substance réticulée la voie réticulo-spinale, et le cortex via le thalamus la voie cortico-spinale.","s":4},{"q":"Le vestibulocervelet correspond anatomiquement :","o":["Au lobe flocculo-nodulaire, partie phylogénétiquement la plus ancienne","Au lobe antérieur","Aux hémisphères latéraux","Au vermis"],"r":0,"e":"Il travaille de façon réciproque avec le système vestibulaire et reçoit également des aires visuelles.","s":4},{"q":"Le spinocervelet reçoit simultanément :","o":["L'intention issue du cortex et le résultat issu des voies spino-cérébelleuses","Uniquement l'information vestibulaire","Uniquement l'information corticale","Uniquement l'information visuelle"],"r":0,"e":"C'est la comparaison entre ces deux flux qui permet de déclencher corrections et ajustements pendant la réalisation du mouvement.","s":4},{"q":"Les fonctions du spinocervelet comprennent :","o":["La correction de l'erreur, la coordination instantanée du mouvement et le contrôle postural dynamique","La planification motrice","Le contrôle des yeux","L'apprentissage moteur"],"r":0,"e":"Il correspond au lobe antérieur et aux régions du vermis et du paravermis, et influence instantanément les motoneurones supérieurs.","s":4},{"q":"Le cérébrocervelet reçoit la majorité de ses fibres :","o":["De la moelle épinière","Du cortex cérébral, avec relais dans les noyaux pontiques","Du système vestibulaire","De l'olive bulbaire"],"r":1,"e":"Ses fonctions sont la planification et la pré-programmation motrice, le timing d'activation, la précision et l'apprentissage moteur.","s":4},{"q":"L'ataxie cérébelleuse se caractérise par un mouvement volontaire :","o":["De force diminuée et rigide","De force normale mais inadapté, incoordonné et imprécis, sans rigidité ni hypertonie","Impossible","Ralenti avec tremblement de repos"],"r":1,"e":"L'absence de déficit de force et d'hypertonie distingue nettement l'atteinte cérébelleuse d'une atteinte de la voie cortico-spinale ou des noyaux gris.","s":4},{"q":"Les lésions unilatérales du cervelet ont des conséquences :","o":["Controlatérales","Homolatérales","Bilatérales","Sans latéralisation"],"r":1,"e":"C'est une différence majeure avec les lésions corticales, dont les effets sont controlatéraux du fait du croisement des voies pyramidales.","s":4},{"q":"La sortie du vestibulocervelet se dirige vers :","o":["Les noyaux vestibulaires, influençant les voies vestibulo-spinales et le réflexe vestibulo-oculaire","Le noyau rouge","Le thalamus uniquement","La substance noire"],"r":0,"e":"Il réagit rapidement pour l'équilibre, les mécanismes posturaux et la locomotion, et coordonne les yeux avec les mouvements de la tête.","s":4},{"q":"La sortie du cérébrocervelet se dirige :","o":["Vers la moelle épinière directement","De nouveau vers le cortex, via le thalamus","Vers les noyaux vestibulaires","Vers l'olive bulbaire"],"r":1,"e":"Cette boucle cortex-cervelet-cortex est ce qui permet d'affiner un programme moteur avant même son exécution.","s":4},{"q":"La dysmétrie se définit comme :","o":["Un tremblement au repos","L'incapacité à évaluer avec précision une distance, une direction ou une amplitude","Une difficulté d'élocution","Une perte de force"],"r":1,"e":"Elle aboutit à un mouvement inadapté, qui dépasse ou n'atteint pas la cible. C'est l'un des signes cardinaux du syndrome cérébelleux.","s":4},{"q":"Le tremblement cérébelleux est dit intentionnel parce qu'il :","o":["Survient au repos","Apparaît pendant le mouvement volontaire, surtout au point où la précision est la plus requise","Est volontairement produit","Disparaît à l'effort"],"r":1,"e":"Cette majoration à l'approche de la cible le distingue nettement du tremblement de repos de la maladie de Parkinson.","s":4},{"q":"La dysdiadococinésie correspond à :","o":["Une difficulté à réaliser des mouvements rapides et alternés, avec incapacité à maintenir un rythme régulier","Une perte de sensibilité","Une paralysie faciale","Une raideur articulaire"],"r":0,"e":"S'y ajoute la difficulté à contrôler la force nécessaire. Le test classique consiste à demander des pronosupinations rapides et alternées.","s":4},{"q":"La décomposition du mouvement s'explique par :","o":["Une faiblesse musculaire","Des erreurs de timing d'activation et la difficulté à stabiliser les articulations proximales contre la force générée en distal","Une atteinte sensitive","Une rigidité"],"r":1,"e":"Le mouvement pluriarticulaire, qui devrait être fluide, se fragmente en séquences successives — d'où son nom.","s":4},{"q":"Dans un mouvement rapide chez le patient cérébelleux :","o":["L'activité agoniste est raccourcie","L'activité de l'agoniste est prolongée et celle de l'antagoniste retardée","Les deux activités sont abolies","L'antagoniste se contracte en premier"],"r":1,"e":"Il en résulte une potentialisation constante de l'agoniste ; chaque tentative de correction reproduit le même défaut, d'où des oscillations répétées.","s":4},{"q":"Le nystagmus et les troubles de l'équilibre avec ataxie du tronc traduisent une atteinte :","o":["Du vestibulocervelet","Du spinocervelet","Du cérébrocervelet","Des noyaux gris centraux"],"r":0,"e":"S'y ajoute la difficulté de fixation oculaire pendant les mouvements de la tête — trois signes qui renvoient à sa collaboration avec le système vestibulaire.","s":4},{"q":"L'hypotonie figure parmi les signes d'atteinte :","o":["Du vestibulocervelet","Du spinocervelet","Du cérébrocervelet","Du cortex moteur"],"r":1,"e":"Elle accompagne la dysmétrie, le tremblement intentionnel, la dysdiadococinésie et la difficulté à réaliser corrections et ajustements pendant le mouvement.","s":4},{"q":"Quels noyaux constituent le striatum ?","o":["Le noyau caudé et le putamen","Le globus pallidus et le putamen","Le noyau sous-thalamique et la substance noire","Le thalamus et le noyau caudé"],"r":0,"e":"Le striatum est le principal noyau récepteur (input) des NGC.","s":5},{"q":"Quels sont les deux noyaux d'output des NGC ?","o":["Le globus pallidus et la substance noire","Le noyau caudé et le putamen","Le thalamus et le noyau sous-thalamique","Le noyau rouge et la substance réticulée"],"r":0,"e":"Le striatum est le noyau d'entrée.","s":5},{"q":"À quelle structure appartient le noyau sous-thalamique ?","o":["Au diencéphale","Au mésencéphale","Au télencéphale","Au métencéphale"],"r":0,"e":"La substance noire appartient au mésencéphale.","s":5},{"q":"À quelle structure appartient la substance noire ?","o":["Au mésencéphale","Au diencéphale","Au télencéphale","Au bulbe"],"r":0,"e":"Le noyau sous-thalamique appartient au diencéphale.","s":5},{"q":"Les NGC ont-ils des connexions directes avec les neurones moteurs ?","o":["Non, et ils ne reçoivent pas non plus d'input direct de la moelle épinière","Oui, directement avec les motoneurones alpha","Oui, via la voie rubro-spinale","Oui, via la voie cortico-spinale directe"],"r":0,"e":"Leur influence passe par les communications avec les aires motrices du cortex.","s":5},{"q":"Quel est le principal noyau récepteur des NGC ?","o":["Le striatum","Le globus pallidus","La substance noire","Le noyau sous-thalamique"],"r":0,"e":"Il reçoit presque toutes les régions du cortex et le thalamus.","s":5},{"q":"De quelles régions le striatum reçoit-il l'information ?","o":["De presque toutes les régions du cortex — surtout motrices, mais aussi sensorielles, associatives et limbiques — et du thalamus","De la moelle épinière","Du cervelet uniquement","Du tronc cérébral uniquement"],"r":0,"e":"L'information ressort ensuite par le globus pallidus et la substance noire.","s":5},{"q":"Où l'information des NGC retourne-t-elle après traitement ?","o":["Vers le thalamus puis vers les aires de planification motrice et le cortex moteur primaire","Directement vers la moelle épinière","Vers le cervelet","Vers les récepteurs périphériques"],"r":0,"e":"Elle influence les systèmes descendants, notamment les voies cortico-spinales.","s":5},{"q":"Comment décrit-on le circuit moteur des NGC ?","o":["Comme une boucle sous-corticale ramenant le feedback des aires motrices et somatosensorielles vers le cortex moteur","Comme une voie descendante directe","Comme un arc réflexe","Comme une voie ascendante sensorielle"],"r":0,"e":"Elle passe par les différents NGC et le thalamus.","s":5},{"q":"Quel circuit des NGC est associé aux mouvements saccadiques des yeux ?","o":["Le circuit oculomoteur","Le circuit préfrontal dorsolatéral","Le circuit orbitofrontal latéral","Le circuit moteur"],"r":0,"e":"Le circuit préfrontal dorsolatéral est associé à la mémoire.","s":5},{"q":"Quel circuit des NGC est associé au comportement ?","o":["Le circuit orbitofrontal latéral","Le circuit oculomoteur","Le circuit préfrontal dorsolatéral","Le circuit moteur"],"r":0,"e":"Le circuit préfrontal dorsolatéral concerne la mémoire.","s":5},{"q":"En quoi consiste le principe de désinhibition ?","o":["Une structure inhibe une deuxième, dont l'output inhibe une troisième, ce qui augmente l'activité de la troisième","Une structure excite directement une autre","Deux structures s'inhibent mutuellement","Une structure bloque toute activité en aval"],"r":0,"e":"L'inhibition de la deuxième structure réduit son output inhibiteur sur la troisième.","s":5},{"q":"Quel est l'effet de la voie directe des NGC ?","o":["Une désinhibition du thalamus qui facilite l'activation corticale et le mouvement","Une inhibition du thalamus","Une désinhibition du noyau sous-thalamique","Une inhibition du cortex moteur"],"r":0,"e":"La voie indirecte, par désinhibition du noyau sous-thalamique, inhibe le thalamus.","s":5},{"q":"Quel est l'effet de la voie indirecte des NGC ?","o":["Une désinhibition du noyau sous-thalamique qui aboutit à une inhibition du thalamus","Une désinhibition du thalamus","Une facilitation du mouvement","Une inhibition du striatum"],"r":0,"e":"La voie directe désinhibe au contraire le thalamus.","s":5},{"q":"Comment les NGC participent-ils à l'apprentissage moteur ?","o":["Ils renforcent les comportements souhaités et réussis et suppriment les autres, en sélectionnant les programmes appropriés au contexte","Ils corrigent l'erreur instantanément","Ils planifient les mouvements guidés visuellement","Ils règlent le timing des agonistes et antagonistes"],"r":0,"e":"C'est l'apprentissage « par la récompense », lié à l'automatisation.","s":5},{"q":"Avec quelle aire corticale les NGC entretiennent-ils une relation liée à l'objectif et à l'anticipation des conséquences ?","o":["L'aire préfrontale","L'aire prémotrice","Le cortex visuel","L'aire de Broca"],"r":0,"e":"Le cervelet est plutôt en relation avec l'aire prémotrice.","s":5},{"q":"Quel type de mouvement les NGC automatisent-ils ?","o":["Les mouvements produits en interne et les séquences de mouvement","Les mouvements guidés visuellement","Les réflexes médullaires","Les mouvements rythmiques générés par les CPG"],"r":0,"e":"Ils contribuent aussi à l'initiation du mouvement.","s":5},{"q":"Quel rôle de « frein » les NGC exercent-ils ?","o":["Ils facilitent (désinhibent) ou suppriment le mouvement volontaire généré en interne","Ils bloquent les afférences sensorielles","Ils inhibent le cervelet","Ils suppriment les réflexes"],"r":0,"e":"Ils contrôlent aussi la « quantité » de mouvement en contextualisant celui-ci.","s":5},{"q":"Une lésion des NGC provoque-t-elle une paralysie ?","o":["Non, elle ne cause ni parésie ni paralysie, mais elle affecte la performance motrice","Oui, une paralysie complète","Oui, une parésie distale","Oui, une hémiplégie"],"r":0,"e":"Elle entraîne aussi des déficits de motivation, d'attention et de sélection entre les mouvements.","s":5},{"q":"Que se passe-t-il si l'output inhibiteur des NGC est excessif ?","o":["On observe des désordres hypokinétiques","On observe des désordres hyperkinétiques","On observe une ataxie","Rien ne se produit"],"r":0,"e":"Une inhibition inadéquate produit au contraire des désordres hyperkinétiques.","s":5},{"q":"Comment définit-on la rigidité ?","o":["Une augmentation de la résistance au mouvement passif et actif dans tous les muscles, assimilable à une augmentation du tonus","Une incapacité à initier le mouvement","Un ralentissement du mouvement","Un tremblement au repos"],"r":0,"e":"Elle produit une contraction excessive des muscles posturaux.","s":5},{"q":"Qu'est-ce que l'akinésie ?","o":["L'incapacité à initier le mouvement","La diminution de l'amplitude et de la vitesse","L'augmentation du tonus","Un mouvement involontaire rapide"],"r":0,"e":"La bradykinésie correspond à la diminution de l'amplitude et de la vitesse.","s":5},{"q":"Que recouvre la bradykinésie ?","o":["Diminution de l'amplitude et de la vitesse du mouvement volontaire, y compris de l'expression faciale et du ballant des bras","L'incapacité d'initier le mouvement","Une rigidité musculaire","Des mouvements choréiques"],"r":0,"e":"Elle s'accompagne d'un ralentissement des réponses posturales.","s":5},{"q":"Quand survient le tremblement des désordres hypokinétiques ?","o":["Au repos","Pendant le mouvement volontaire","À la fin du mouvement","Pendant le sommeil"],"r":0,"e":"Le tremblement intentionnel, lui, est d'origine cérébelleuse.","s":5},{"q":"Comment se comportent les dyskinésies pendant le sommeil ?","o":["Elles disparaissent","Elles s'aggravent","Elles restent identiques","Elles deviennent rythmiques"],"r":0,"e":"Elles augmentent au contraire pendant l'activité et le stress émotionnel.","s":5},{"q":"Quelle forme de dystonie est la plus fréquente ?","o":["La dystonie focale, localisée à une seule zone corporelle","La dystonie segmentaire","La dystonie généralisée","La dystonie multifocale"],"r":0,"e":"La dystonie généralisée s'observe par exemple dans la maladie de Huntington.","s":5},{"q":"Comment se caractérise la chorée ?","o":["Des mouvements involontaires, irréguliers, inadaptés et rapides, continus et alternés, variant toujours de schéma et de segment","Des mouvements lents et tordus","Un tremblement de repos","Une rigidité"],"r":0,"e":"Une chorée très marquée peut prendre le nom de ballisme.","s":5},{"q":"Comment se caractérise l'athétose ?","o":["Des mouvements plus lents que la chorée, « tordus », plus fréquents aux mains et aux pieds","Des mouvements rapides et alternés","Un tremblement intentionnel","Une akinésie"],"r":0,"e":"Elle s'observe souvent chez les enfants atteints de paralysie cérébrale ; associée à la chorée on parle de choréoathétose.","s":5},{"q":"Quelle est la lésion caractéristique de la maladie de Parkinson ?","o":["La mort des cellules productrices de dopamine au niveau de la substance noire","Une atteinte du striatum","Une lésion du noyau sous-thalamique","Une atrophie cérébelleuse"],"r":0,"e":"C'est le trouble moteur le plus fréquent ayant pour origine les NGC.","s":5},{"q":"Quelle formule résume les rôles respectifs du cortex, du cervelet et des NGC ?","o":["Le mouvement est défini par le cortex, coordonné et affiné par le cervelet et automatisé par les noyaux gris centraux","Le mouvement est défini par le cervelet et automatisé par le cortex","Les NGC définissent et le cortex coordonne","Le cervelet définit et automatise"],"r":0,"e":"L'information est ensuite transmise par les voies descendantes jusqu'aux motoneurones.","s":5},{"q":"Le striatum est formé par :","o":["Le noyau caudé et le putamen","Le globus pallidus et le putamen","Le noyau sous-thalamique et la substance noire","Le thalamus et le noyau caudé"],"r":0,"e":"Il constitue le noyau d'entrée. Le globus pallidus et la substance noire sont les noyaux de sortie, le noyau sous-thalamique un relais du circuit.","s":5},{"q":"Le noyau sous-thalamique appartient anatomiquement :","o":["Au diencéphale","Au mésencéphale","Au télencéphale","Au métencéphale"],"r":0,"e":"La substance noire appartient au mésencéphale ; le striatum et le globus pallidus sont des noyaux cérébraux.","s":5},{"q":"Les noyaux gris centraux exercent leur influence :","o":["Par des connexions directes avec les neurones moteurs","Principalement par leurs communications avec les aires motrices du cortex","Par la moelle épinière directement","Par les nerfs périphériques"],"r":1,"e":"Ils ne reçoivent pas non plus d'input direct de la moelle épinière : ils fonctionnent en boucle avec le cortex.","s":5},{"q":"Le striatum reçoit l'information :","o":["De la seule aire motrice primaire","De presque toutes les régions du cortex, ainsi que du thalamus","Du cervelet","De la moelle épinière"],"r":1,"e":"Outre les aires motrices, il reçoit des aires sensorielles, associatives et limbiques — ce qui explique ses fonctions cognitives et émotionnelles.","s":5},{"q":"Le circuit oculomoteur des noyaux gris centraux contrôle :","o":["Les mouvements saccadiques des yeux","La mémoire","Le comportement","La posture"],"r":0,"e":"Le circuit préfrontal dorsolatéral concerne la mémoire, le circuit orbitofrontal latéral le comportement.","s":5},{"q":"La voie directe des noyaux gris centraux aboutit à :","o":["Une inhibition du thalamus","Une désinhibition du thalamus, qui facilite l'activation corticale et le mouvement","Une inhibition du cortex","Une activation du cervelet"],"r":1,"e":"La voie indirecte passe par la désinhibition du noyau sous-thalamique, qui aboutit au contraire à une inhibition du thalamus.","s":5},{"q":"Le principe de désinhibition se formule ainsi :","o":["Une structure active une deuxième, qui active une troisième","Une structure inhibe une deuxième, dont l'output inhibe une troisième, ce qui augmente l'activité de cette dernière","Deux structures s'inhibent mutuellement","Une structure s'auto-inhibe"],"r":1,"e":"Inhiber l'inhibiteur revient à libérer la cible. Le cours souligne que beaucoup de ces mécanismes restent mal compris.","s":5},{"q":"Parmi les fonctions des noyaux gris centraux, l'apprentissage moteur « par la récompense » consiste à :","o":["Renforcer les comportements souhaités et réussis et supprimer les autres","Corriger l'erreur en temps réel","Planifier le mouvement","Maintenir l'équilibre"],"r":0,"e":"Ils sélectionnent ainsi les programmes moteurs et comportementaux appropriés à un contexte donné, ce qui aboutit à l'automatisation.","s":5},{"q":"Composer un numéro de téléphone est cité comme exemple :","o":["De mouvement réflexe","De mouvement automatique, répétitif et inconscient","De mouvement balistique","De contrôle postural"],"r":1,"e":"Les noyaux gris centraux sont, avec le cortex, le principal centre responsable de ce type de mouvements.","s":5},{"q":"Une lésion des noyaux gris centraux :","o":["Provoque une parésie ou une paralysie","Ne cause ni parésie ni paralysie, mais affecte la performance motrice","Abolit toute sensibilité","Entraîne une ataxie cérébelleuse"],"r":1,"e":"S'y ajoutent des déficits de motivation et d'attention, et une difficulté à sélectionner entre les mouvements.","s":5},{"q":"La rigidité, désordre hypokinétique, se caractérise par :","o":["Une résistance au mouvement passif uniquement","Une augmentation de la résistance au mouvement passif et actif dans tous les muscles","Une hypotonie","Un tremblement d'action"],"r":1,"e":"Son effet sur les voies descendantes produit une contraction excessive des muscles posturaux. On peut la considérer comme une augmentation du tonus.","s":5},{"q":"La bradykinésie désigne :","o":["L'incapacité à initier le mouvement","La diminution de l'amplitude et de la vitesse du mouvement volontaire","Des mouvements involontaires rapides","Une augmentation du tonus"],"r":1,"e":"Elle touche aussi l'expression faciale et le ballant des bras à la marche, et ralentit les réponses posturales. L'akinésie désigne l'incapacité à initier.","s":5},{"q":"Le tremblement des désordres hypokinétiques survient :","o":["Pendant le mouvement","Au repos","À l'approche de la cible","Uniquement la nuit"],"r":1,"e":"Cela l'oppose au tremblement intentionnel cérébelleux, qui apparaît pendant le mouvement volontaire et s'accentue près de la cible.","s":5},{"q":"La dystonie se distingue des troubles cérébelleux notamment parce qu'elle :","o":["Est associée au mouvement volontaire","N'est pas associée au mouvement volontaire, augmente pendant l'activité et le stress émotionnel, et disparaît pendant le sommeil","Ne varie jamais","Touche uniquement les membres inférieurs"],"r":1,"e":"Ses formes vont de la dystonie focale, la plus fréquente, aux formes segmentaires, multifocales et généralisées comme dans la maladie de Huntington.","s":5},{"q":"La chorée se caractérise par des mouvements involontaires :","o":["Lents et tordus","Irréguliers, inadaptés et rapides, continus et alternés, variant de schéma et de segment","Rythmiques et réguliers","Limités à une articulation"],"r":1,"e":"Une chorée très marquée peut prendre le nom de ballisme. Elle s'observe notamment dans la maladie de Huntington.","s":5},{"q":"L'athétose se distingue de la chorée par :","o":["Sa plus grande rapidité","Sa lenteur et ses mouvements « tordus », plus fréquents aux mains et aux pieds","Son caractère rythmique","Son absence de mouvement involontaire"],"r":1,"e":"Elle s'observe souvent chez les enfants atteints de paralysie cérébrale. Associée à la chorée, on parle de choréoathétose.","s":5},{"q":"La maladie de Parkinson résulte de :","o":["La mort des cellules productrices de dopamine dans la substance noire","Une lésion du cervelet","Une atteinte du cortex moteur","Une dégénérescence du thalamus"],"r":0,"e":"C'est le trouble moteur le plus fréquent ayant pour origine les noyaux gris centraux, et le prototype des désordres hypokinétiques.","s":5},{"q":"La formule de synthèse du cours énonce que le mouvement est :","o":["Défini par le cortex, coordonné et affiné par le cervelet, automatisé par les noyaux gris centraux","Défini par le cervelet, coordonné par le cortex","Entièrement produit par la moelle épinière","Contrôlé uniquement par les voies descendantes"],"r":0,"e":"L'information est ensuite transmise par les voies descendantes jusqu'aux motoneurones, qui l'acheminent aux fibres musculaires.","s":5},{"q":"Les noyaux gris centraux sont associés aux mouvements générés en interne, en relation avec :","o":["L'aire prémotrice","L'aire motrice supplémentaire et l'aire préfrontale","Le cortex visuel","Le cortex pariétal postérieur"],"r":1,"e":"Le cervelet est plutôt associé aux mouvements déclenchés et guidés visuellement, en relation avec l'aire prémotrice.","s":5},{"q":"Parmi les points communs entre cervelet et noyaux gris centraux, le cours cite :","o":["L'absence de connexions directes avec les neurones moteurs","Une action directe sur la moelle épinière","Une fonction sensitive","Une commande des réflexes"],"r":0,"e":"Tous deux influencent les circuits moteurs via le thalamus et le tronc cérébral, sont liés à l'apprentissage moteur par la pratique et à la mémoire inconsciente des habiletés.","s":5},{"q":"Comment définit-on la neuroplasticité ?","o":["La capacité du SN à modifier sa fonction, sa structure et son profil chimique selon l'usage qui lui est donné","La capacité de régénérer les neurones morts","La croissance du cerveau pendant l'enfance","La myélinisation des axones"],"r":0,"e":"C'est une propriété intrinsèque du système nerveux, maintenue tout au long du cycle de vie.","s":6},{"q":"Que devient une synapse non utilisée ?","o":["Elle se perd, tandis que les synapses utilisées s'étendent et se renforcent","Elle reste identique","Elle se renforce","Elle se dédouble"],"r":0,"e":"La neuroplasticité est le mécanisme qui permet l'apprentissage, la croissance et le développement.","s":6},{"q":"Quelle formule résume la relation forme-fonction ?","o":["La forme anatomique détermine la fonction présente ; la fonction détermine la forme du futur","La forme est immuable","La fonction ne modifie jamais la forme","La forme suit toujours la génétique"],"r":0,"e":"La plasticité est présente à tous les niveaux du SNC, dans le SNP et au niveau musculaire.","s":6},{"q":"Que se passe-t-il au niveau cortical lorsqu'on entraîne une tâche déterminée ?","o":["Augmentation du nombre et de la densité des synapses, et donc de l'aire de représentation","Diminution de l'aire de représentation","Aucun changement structurel","Perte de myéline"],"r":0,"e":"Les cartes corticales sont modifiées par l'input sensoriel, l'expérience et l'apprentissage.","s":6},{"q":"Combien de temps par jour les sujets s'entraînaient-ils dans l'étude de Pascual-Leone (1996) ?","o":["2 heures par jour","30 minutes","4 heures","20 minutes"],"r":0,"e":"L'entraînement était suivi d'un test de 20 répétitions, sur 5 jours consécutifs.","s":6},{"q":"Quelle technique a servi à analyser les cartes corticales dans l'étude de Pascual-Leone ?","o":["La stimulation électrique transcrânienne","L'IRM fonctionnelle","L'électromyographie","La tomographie par émission de positons"],"r":0,"e":"Elle était utilisée quotidiennement, bilatéralement, pour les fléchisseurs et extenseurs des doigts.","s":6},{"q":"Quels résultats ont été observés après une semaine d'entraînement au piano ?","o":["Moins d'erreurs, plus de précision et de coordination, seuil d'excitabilité diminué et représentation corticale augmentée","Une augmentation du nombre d'erreurs","Une diminution de la représentation corticale","Aucun changement"],"r":0,"e":"L'augmentation était présente tant avant qu'après la séance pratique.","s":6},{"q":"Qu'est-il arrivé aux cartes corticales du groupe ayant cessé de pratiquer ?","o":["Elles sont revenues aux valeurs de base et sont restées stables","Elles ont continué d'augmenter","Elles ont disparu","Elles ont doublé"],"r":0,"e":"Le groupe ayant poursuivi a vu sa représentation s'affiner au fil des semaines.","s":6},{"q":"Pourquoi la représentation corticale diminue-t-elle au fil des semaines chez le groupe entraîné ?","o":["Du fait de l'affinement de la tâche et de l'activité corticale","Parce que l'apprentissage échoue","Par fatigue neuronale","Par perte de synapses"],"r":0,"e":"La tâche se développe et s'affine en même temps que l'aire corticale se « sédimente ».","s":6},{"q":"Quel a été le résultat de la pratique MENTALE dans l'étude de Pascual-Leone ?","o":["Une réorganisation semblable des outputs moteurs","Aucun effet","Une diminution de la représentation","Un effet inverse"],"r":0,"e":"C'est un résultat qualifié d'étonnant dans le cours.","s":6},{"q":"Quelles sont les périodes critiques de la neuroplasticité citées ?","o":["Enfance/adolescence, entraînement de tâches nouvelles et lésion du SN","Uniquement l'enfance","Uniquement après une lésion","La vieillesse"],"r":0,"e":"La plasticité reste toutefois présente tout au long du cycle de vie.","s":6},{"q":"Quel neurotransmetteur est au cœur de la potentialisation à long terme ?","o":["Le glutamate","La dopamine","L'acétylcholine","Le GABA"],"r":0,"e":"Il agit sur les récepteurs AMPA et NMDA.","s":6},{"q":"Quel est le rôle des récepteurs AMPA ?","o":["Ce sont des canaux ioniques permettant le passage d'ions positifs","Ils modifient l'efficacité de la synapse","Ils dégradent le glutamate","Ils inhibent la transmission"],"r":0,"e":"Les récepteurs NMDA sont responsables des modifications de l'efficacité de la synapse.","s":6},{"q":"Que produit la potentialisation à long terme ?","o":["Un réveil des synapses silencieuses, avec augmentation du nombre de récepteurs AMPA et de la force de la synapse","Une diminution des récepteurs AMPA","Une destruction des synapses","Une inhibition du glutamate"],"r":0,"e":"La dépression à long terme diminue au contraire le nombre de récepteurs AMPA.","s":6},{"q":"Où se trouvent majoritairement les récepteurs AMPA d'une synapse silencieuse ?","o":["Dans le cytoplasme, et non dans la membrane cellulaire","Dans la membrane","Dans la fente synaptique","Dans l'axone pré-synaptique"],"r":0,"e":"L'entrée de calcium favorise leur migration vers la membrane.","s":6},{"q":"Quel ion initie la potentialisation à long terme ?","o":["Le calcium","Le sodium","Le potassium","Le chlore"],"r":0,"e":"Son entrée survient lors d'une stimulation simultanée par le glutamate et d'une dépolarisation.","s":6},{"q":"Quelle est la dernière étape structurelle de la PLT ?","o":["Des altérations de la membrane post-synaptique avec création de nouvelles épines dendritiques indépendantes","La migration des récepteurs AMPA","L'entrée du calcium","La libération de glutamate"],"r":0,"e":"Elle est précédée du remodelage de la membrane pré-synaptique avec création de nouvelles synapses.","s":6},{"q":"Quelle est la limite de la potentialisation à COURT terme ?","o":["Elle conduit à des modifications non stables, qui s'inversent facilement sans répétition","Elle est irréversible","Elle détruit les synapses","Elle n'existe pas"],"r":0,"e":"Elle est le premier phénomène à survenir après une stimulation de haute intensité.","s":6},{"q":"Quel type de stimuli induit une dépression à long terme ?","o":["Des stimuli de basse intensité, basse fréquence et peu répétés dans le temps","Des stimuli de haute intensité","Des stimuli répétés à haute fréquence","Aucun stimulus"],"r":0,"e":"Les stimuli de haute intensité induisent la potentialisation à long terme.","s":6},{"q":"Comment évolue l'activation cérébrale au cours de l'apprentissage ?","o":["Beaucoup d'aires sont actives au début, puis l'activation devient moindre et plus précise","Elle augmente progressivement","Elle reste constante","Elle disparaît"],"r":0,"e":"Cela traduit une spécialisation inhérente au processus d'apprentissage.","s":6},{"q":"Quelle lésion conduit invariablement à la mort cellulaire ?","o":["La destruction du corps cellulaire du neurone","La lésion de l'axone","La compression par œdème","La démyélinisation"],"r":0,"e":"Certains neurones ont la capacité de régénérer leur axone.","s":6},{"q":"Qu'est-ce que la dégénérescence wallérienne ?","o":["La dégénérescence du segment distal de l'axone, éloigné du corps cellulaire, suivie de sa mort","La mort du corps cellulaire","La régénération de l'axone","La création de nouvelles synapses"],"r":0,"e":"Elle peut aboutir à la dégénérescence de la cellule post-synaptique.","s":6},{"q":"Qu'est-ce que le bourgeonnement collatéral ?","o":["La réinnervation d'une cible dénervée par des ramifications d'axones intacts de neurones voisins","L'envoi de ramifications par un axone lésé vers une nouvelle cible","La création de nouvelles épines dendritiques","La migration des récepteurs AMPA"],"r":0,"e":"Le bourgeonnement régénératif concerne un axone et sa cellule cible tous deux lésés.","s":6},{"q":"Qu'est-ce que le bourgeonnement régénératif ?","o":["Un axone lésé, dont la cellule cible a aussi été lésée, envoie des ramifications vers une nouvelle cible","Un axone intact réinnerve une cible dénervée","La création de nouvelles synapses silencieuses","La récupération de l'efficacité synaptique"],"r":0,"e":"La régénération axonale survient plus fréquemment dans le SNP.","s":6},{"q":"Pourquoi la régénération axonale peut-elle être préjudiciable ?","o":["Parce qu'une cible inappropriée peut être innervée, causant des mouvements indésirables ou une confusion des modalités sensorielles","Parce qu'elle est trop lente","Parce qu'elle consomme trop d'énergie","Parce qu'elle détruit la myéline"],"r":0,"e":"Des axones moteurs peuvent innerver des muscles différents de ceux d'origine.","s":6},{"q":"Qu'est-ce que la récupération de l'efficacité synaptique ?","o":["Le rétablissement du fonctionnement normal après résorption de l'œdème qui comprimait les corps cellulaires pré-synaptiques","Le développement de nouveaux sites de réception","La concentration des neurotransmetteurs sur les ramifications restantes","La création de nouvelles synapses"],"r":0,"e":"L'œdème produit une ischémie focale rendant certaines synapses inactives.","s":6},{"q":"Qu'est-ce que l'hypersensibilité post-dénervation ?","o":["Le développement de nouveaux sites de réception post-synaptiques après destruction des terminaisons pré-synaptiques","La concentration des neurotransmetteurs sur les ramifications restantes","La résorption d'un œdème","La création d'épines dendritiques"],"r":0,"e":"Elle survient en réponse aux transmetteurs libérés par d'autres axones.","s":6},{"q":"Qu'est-ce que l'hyperefficacité synaptique ?","o":["Seules certaines ramifications pré-synaptiques sont détruites, et les restantes reçoivent tous les neurotransmetteurs","Toutes les terminaisons sont détruites","De nouveaux récepteurs apparaissent","La fente synaptique s'élargit"],"r":0,"e":"Il en résulte une plus grande quantité de neurotransmetteurs libérée sur les récepteurs post-synaptiques.","s":6},{"q":"Quel est l'effet du stress chronique sur la neuroplasticité ?","o":["Il est neurotoxique par le cortisol, au niveau de la mémoire et de l'apprentissage (hippocampe)","Il augmente la mémoire","Il n'a aucun effet","Il favorise la synaptogenèse"],"r":0,"e":"Le stress aigu peut au contraire augmenter la mémoire et la vigilance.","s":6},{"q":"Que dit le principe « interference » de Kleim & Jones ?","o":["Une intervention inadéquate favorisant des stratégies compensatoires peut interférer avec le potentiel de récupération","Il faut répéter le plus possible","L'expérience doit être significative","La plasticité diminue avec l'âge"],"r":0,"e":"La meilleure solution du présent peut ne pas être la meilleure pour l'avenir.","s":6},{"q":"La plasticité est définie comme :","o":["Une capacité limitée à l'enfance","Une propriété intrinsèque du système nerveux, maintenue tout au long du cycle de vie","Une réaction pathologique","Un mécanisme exclusivement cortical"],"r":1,"e":"Elle désigne la capacité à modifier fonction, structure et profil chimique — nombre et type de neurotransmetteurs — selon l'usage.","s":6},{"q":"La formule du cours sur forme et fonction énonce que :","o":["La forme détermine la fonction présente, et la fonction détermine la forme du futur","La fonction ne dépend pas de la forme","La forme est immuable","La fonction précède toujours la forme"],"r":0,"e":"C'est le fondement théorique de la rééducation : agir sur la fonction aujourd'hui, c'est modifier la structure de demain.","s":6},{"q":"Les synapses, selon le cours :","o":["Sont fixées dès la naissance","S'étendent et se renforcent avec l'usage, et se perdent avec le non-usage","Se renouvellent aléatoirement","Ne varient qu'après lésion"],"r":1,"e":"Avec l'expérience, certaines cellules et synapses s'éliminent tandis que d'autres s'organisent, selon l'activité et l'exigence.","s":6},{"q":"La plasticité est présente :","o":["Uniquement dans le cortex","À tous les niveaux du système nerveux central, dans le système nerveux périphérique et au niveau musculaire","Uniquement dans la moelle épinière","Uniquement chez l'enfant"],"r":1,"e":"Cette généralité justifie qu'un entraînement produise des effets simultanés sur la commande, la conduction et l'effecteur.","s":6},{"q":"L'entraînement d'une tâche déterminée produit :","o":["Une diminution du nombre de synapses","Une augmentation du nombre et de la densité des synapses, donc de l'aire de représentation corticale","Une atrophie corticale","Aucun changement structurel"],"r":1,"e":"C'est ce qu'a montré l'étude de Pascual-Leone en 1996 sur l'apprentissage d'un morceau de piano.","s":6},{"q":"Dans l'étude de Pascual-Leone, le protocole comportait :","o":["2 heures de pratique par jour pendant 5 jours consécutifs, suivies d'un test de 20 répétitions","30 minutes par semaine","Une séance unique","Un entraînement mental uniquement"],"r":0,"e":"La stimulation électrique transcrânienne analysait quotidiennement les cartes corticales des fléchisseurs et extenseurs des doigts, bilatéralement.","s":6},{"q":"Après une semaine dans l'étude de Pascual-Leone :","o":["Aucun changement n'était observé","Le nombre d'erreurs avait diminué, la précision et la coordination augmenté, le seuil d'excitabilité baissé et la représentation corticale augmenté","Seule la performance s'améliorait","La représentation corticale diminuait"],"r":1,"e":"Ces changements s'observaient aussi bien avant qu'après la séance de pratique du jour, ce qui atteste d'une modification durable.","s":6},{"q":"Après cinq semaines de pratique poursuivie, la représentation corticale :","o":["Continue d'augmenter indéfiniment","Diminue au fil des semaines, du fait de l'affinement de la tâche et de l'activité corticale","Revient au niveau initial","Disparaît"],"r":1,"e":"La tâche se développe et s'affine en même temps que l'aire corticale se structure et se sédimente : l'expertise consomme moins de territoire.","s":6},{"q":"La potentialisation à long terme met en jeu :","o":["Le GABA et les récepteurs GABA-A","Le glutamate et les récepteurs AMPA et NMDA","La dopamine","L'acétylcholine"],"r":1,"e":"L'entrée de calcium fait migrer les récepteurs AMPA vers la membrane et réveille les synapses dites silencieuses.","s":6},{"q":"Le bourgeonnement collatéral consiste en :","o":["L'envoi de ramifications par l'axone lésé vers une nouvelle cible","La réinnervation d'une cible dénervée par des axones intacts voisins","La repousse du corps cellulaire","La formation de nouveaux neurones"],"r":1,"e":"Le bourgeonnement régénératif désigne au contraire l'axone lésé qui envoie lui-même des ramifications vers une nouvelle cible.","s":6},{"q":"Le principe « use it or lose it » de Kleim et Jones (2008) signifie que :","o":["L'entraînement intensif est toujours nécessaire","Une fonction non sollicitée se dégrade","L'âge n'a pas d'importance","La spécificité prime"],"r":1,"e":"Il se double du principe « use it and improve it » : la sollicitation ne se contente pas de préserver, elle améliore.","s":6},{"q":"Le principe de « salience » chez Kleim et Jones souligne que :","o":["L'intensité doit être maximale","L'expérience doit être suffisamment signifiante pour le sujet pour induire un changement plastique","La répétition suffit","Le transfert est automatique"],"r":1,"e":"Une tâche sans enjeu pour la personne mobilise peu les circuits de récompense et produit moins de plasticité, à quantité de pratique égale.","s":6},{"q":"Le principe d'« interference » dans la liste de Kleim et Jones désigne :","o":["Le fait qu'une plasticité acquise peut gêner l'acquisition ultérieure d'une autre fonction","Le bruit pendant l'entraînement","Les interactions médicamenteuses","La fatigue"],"r":0,"e":"C'est un argument majeur contre les compensations précoces mal choisies : ce qui est appris tôt et durablement peut bloquer une récupération plus fonctionnelle.","s":6},{"q":"Le principe de « transference » signifie que :","o":["La plasticité induite par un entraînement peut faciliter l'acquisition de comportements voisins","L'entraînement doit être transféré à domicile","Le patient doit changer de thérapeute","L'effet se transmet d'un hémisphère à l'autre"],"r":0,"e":"Les dix principes comprennent aussi la spécificité, la répétition, l'intensité, le temps et l'âge.","s":6},{"q":"Le cerveau humain est « façonné », selon le cours, par :","o":["Les seuls facteurs génétiques","Les variations des exigences de l'environnement, les modifications physiologiques et l'expérience","Le hasard","L'alimentation"],"r":1,"e":"Toute altération de l'input afférent ou des objectifs entraîne une réorganisation observable du comportement jusqu'au niveau moléculaire.","s":6},{"q":"Dans l'étude de Pascual-Leone, le groupe 2 :","o":["Poursuivait la pratique cinq semaines de plus","Cessait de pratiquer","Doublait le temps de pratique","Changeait de morceau"],"r":1,"e":"La comparaison entre les deux groupes permet de distinguer ce qui relève du maintien par la pratique de ce qui persiste après son arrêt.","s":6},{"q":"La neuroplasticité est présentée comme le mécanisme qui permet :","o":["L'apprentissage, la croissance et le développement","La seule récupération après lésion","La croissance osseuse","Le vieillissement"],"r":0,"e":"C'est pourquoi elle n'est pas seulement un phénomène de réparation : elle sous-tend aussi l'acquisition normale des habiletés tout au long de la vie.","s":6},{"q":"Les deux grandes familles de mécanismes plastiques distinguées par le cours sont :","o":["La potentialisation à long terme, liée à l'apprentissage et à la mémoire, et les altérations post-lésion axonales et synaptiques","La croissance et la dégénérescence","L'inhibition et l'excitation","La myélinisation et la démyélinisation"],"r":0,"e":"Le bourgeonnement collatéral et le bourgeonnement régénératif relèvent de la seconde famille.","s":6},{"q":"Les synapses dites « silencieuses » sont réveillées lors de la potentialisation à long terme par :","o":["La libération de GABA","La migration des récepteurs AMPA vers la membrane sous l'effet de l'entrée de calcium","La dégénérescence axonale","La myélinisation"],"r":1,"e":"Ces synapses existaient déjà anatomiquement mais ne transmettaient pas : leur recrutement est un mécanisme rapide de réorganisation.","s":6},{"q":"La réorganisation induite par une modification de l'input afférent se reflète :","o":["Uniquement au niveau comportemental","Au niveau du comportement, de l'anatomie, de la physiologie, ainsi qu'aux niveaux cellulaire et moléculaire","Uniquement au niveau cellulaire","Uniquement au niveau cortical"],"r":1,"e":"Cette convergence d'échelles est ce qui donne à la plasticité son statut de propriété fondamentale plutôt que de phénomène local.","s":6},{"q":"Quelle est la différence entre contrôle moteur et apprentissage moteur ?","o":["Le contrôle moteur porte sur le mouvement déjà acquis, l'apprentissage moteur sur son acquisition ou sa modification","Le contrôle moteur est conscient, l'apprentissage inconscient","Le contrôle moteur est cortical, l'apprentissage médullaire","Il n'y a pas de différence"],"r":0,"e":"L'apprentissage moteur étudie les mécanismes de l'acquisition et/ou de la modification du mouvement.","s":7},{"q":"Comment définit-on l'apprentissage moteur ?","o":["Un ensemble de processus associés à la pratique ou à l'expérience, conduisant à des modifications relativement permanentes de la capacité à produire des actions","Une amélioration ponctuelle de la performance","La maturation du système nerveux","La transmission de connaissances"],"r":0,"e":"Il ne peut pas être mesuré directement : ses résultats sont inférés à partir du comportement.","s":7},{"q":"Peut-on mesurer directement l'apprentissage moteur ?","o":["Non, ses résultats sont inférés à partir du comportement","Oui, par la performance immédiate","Oui, par l'imagerie fonctionnelle","Oui, par électromyographie"],"r":0,"e":"Les modifications à court terme ne sont pas considérées comme de l'apprentissage.","s":7},{"q":"Quelle différence y a-t-il entre enseignement et apprentissage ?","o":["Il peut y avoir une tentative d'enseignement sans qu'il y ait eu apprentissage","Ils sont synonymes","L'enseignement est toujours suivi d'apprentissage","L'apprentissage précède l'enseignement"],"r":0,"e":"L'enseignement vise la transmission de connaissances et de culture.","s":7},{"q":"Qu'est-ce que l'apprentissage latent ?","o":["L'incapacité à manifester objectivement par la performance des compétences déjà acquises","Une performance sans apprentissage","Un apprentissage par imitation","Un apprentissage implicite"],"r":0,"e":"C'est l'apprentissage « endormi » : la performance dépend aussi de la fatigue, de l'anxiété ou de la motivation.","s":7},{"q":"Quel exemple illustre une performance sans apprentissage ?","o":["Un patient qui s'améliore lors d'une séance mais n'a pas maintenu les gains à la suivante","Un athlète qui s'entraîne sans briller en compétition","Un enfant qui imite ses parents","Un élève qui écoute un cours"],"r":0,"e":"L'usage de substances dopantes en est un autre exemple.","s":7},{"q":"Par quelles caractéristiques évalue-t-on l'apprentissage ?","o":["Perfectionnement, cohérence, stabilité, persistance et adaptabilité","Force, vitesse et amplitude","Attention et motivation","Instruction et démonstration"],"r":0,"e":"L'apprentissage est un processus interne impliquant des modifications plus permanentes.","s":7},{"q":"Sur quelles structures repose l'apprentissage explicite ?","o":["Le cortex et l'hippocampe","Le cervelet et les noyaux gris centraux","La moelle épinière","Le tronc cérébral"],"r":0,"e":"Il requiert attention et réflexion et aboutit à des connaissances utilisables consciemment.","s":7},{"q":"Quelle caractéristique définit l'apprentissage implicite ?","o":["Il ne nécessite ni attention ni processus cognitifs et repose sur des processus réflexes et automatiques","Il requiert une attention soutenue","Il permet le rappel conscient d'événements","Il repose sur l'hippocampe"],"r":0,"e":"Il relève de la mémoire non déclarative.","s":7},{"q":"Qu'est-ce que l'habituation ?","o":["La diminution de la réponse à un stimulus répété","L'augmentation de la réponse à un stimulus nocif","L'association entre deux stimuli","L'automatisation d'une tâche"],"r":0,"e":"Elle relève de l'apprentissage non associatif ; exemple : les dysfonctions vestibulaires.","s":7},{"q":"Qu'est-ce que la sensibilisation ?","o":["Une réponse augmentée secondairement à un stimulus menaçant ou nocif","Une diminution de la réponse à un stimulus répété","Un conditionnement classique","Un apprentissage procédural"],"r":0,"e":"Elle peut servir à augmenter la perception du risque dans un entraînement de l'équilibre.","s":7},{"q":"Sur quoi porte le conditionnement classique de Pavlov ?","o":["La relation entre un stimulus et un autre","La relation entre un comportement et une conséquence","La répétition d'un stimulus unique","L'automatisation d'une habitude"],"r":0,"e":"Le conditionnement opérant de Thorndike porte sur la relation comportement-conséquence.","s":7},{"q":"Sur quoi porte le conditionnement opérant de Thorndike ?","o":["La relation entre un comportement et une conséquence, par essai-erreur","La relation entre deux stimuli","La diminution de la réponse à un stimulus","La création d'une habitude automatique"],"r":0,"e":"Il valorise la connaissance du résultat et repose sur le renforcement positif ou négatif.","s":7},{"q":"Quel principe régit le conditionnement opérant ?","o":["Les comportements récompensés tendent à être répétés, ceux suivis d'un stimulus négatif ne le sont pas","Tous les comportements se répètent","Seuls les comportements automatiques persistent","La récompense n'a aucun effet"],"r":0,"e":"C'est un apprentissage par essai-erreur.","s":7},{"q":"Qu'est-ce que l'apprentissage procédural ?","o":["L'apprentissage de tâches réalisées automatiquement, sans attention ni conscience, comme une habitude","Un apprentissage conscient et déclaratif","Un apprentissage par association de stimuli","Une diminution de réponse à un stimulus"],"r":0,"e":"Il se développe par la répétition et s'exprime par l'amélioration de la performance.","s":7},{"q":"Quels sont les quatre traitements de l'apprentissage explicite ?","o":["Encodage, consolidation, stockage et récupération","Attention, motivation, action, résultat","Perception, cognition, action, feedback","Cognitif, associatif, autonome, transfert"],"r":0,"e":"La récupération est sujette à distorsion.","s":7},{"q":"Quelle est la durée de la phase cognitive de l'apprentissage ?","o":["De quelques minutes à quelques jours","De quelques semaines à quelques mois","Des années","Quelques secondes"],"r":0,"e":"La phase associative dure de quelques semaines à quelques mois.","s":7},{"q":"Que caractérise la phase cognitive ?","o":["Beaucoup d'erreurs grossières, un besoin de beaucoup d'information et une forte attention avec verbalisation de l'action","Une automatisation du mouvement","Une diminution des erreurs","Une performance économique"],"r":0,"e":"L'individu a du mal à percevoir où il s'est trompé et quoi faire pour corriger.","s":7},{"q":"Que caractérise la phase associative ?","o":["Augmentation de la cohérence et de la stabilité, diminution des erreurs et développement de références internes de correction","Automatisation complète","Verbalisation constante","Absence de feedback"],"r":0,"e":"La pratique doit alors commencer à être plus exigeante.","s":7},{"q":"Quelle est la durée de la phase autonome ?","o":["Des années","Quelques jours","Quelques semaines","Quelques heures"],"r":0,"e":"Elle correspond à l'automatisation du mouvement, avec un contrôle sous-cortical et périphérique.","s":7},{"q":"Que caractérise la phase autonome ?","o":["Une prestation indépendante de l'attention consciente, avec un contrôle sous-cortical et périphérique et une performance efficace et économique","Beaucoup d'erreurs grossières","Un besoin constant de feedback externe","Une verbalisation de l'action"],"r":0,"e":"Le focus se déplace vers d'autres aspects pertinents : anticipation, stratégie, esthétique.","s":7},{"q":"Dans quelle catégorie de facteurs classe-t-on la motivation ?","o":["Les facteurs préalables","Les facteurs concomitants","Les facteurs postérieurs","Aucune"],"r":0,"e":"Sans motivation, il n'est pas possible d'apprendre.","s":7},{"q":"Quels sont les facteurs concomitants de l'apprentissage ?","o":["La pratique motrice et la fatigue","L'instruction et la démonstration","L'information de retour sur le résultat","La motivation et l'anticipation"],"r":0,"e":"L'IRR est un facteur postérieur.","s":7},{"q":"Qu'apporte l'instruction par rapport à la démonstration ?","o":["Elle fournit l'information sur l'objectif et la forme de performance et offre des critères de réussite ; en phase initiale, elle peut être plus importante","Elle repose sur l'observation et l'imitation","Elle remplace le feedback","Elle est toujours secondaire"],"r":0,"e":"La démonstration présente une image représentative de la tâche.","s":7},{"q":"En quoi doit consister l'échauffement selon le cours ?","o":["En des activités liées à l'action à réaliser — activation dirigée","En un footing général","En des étirements passifs","En une relaxation"],"r":0,"e":"Il prépare l'individu sur les plans physiologique et psychologique.","s":7},{"q":"Qu'est-ce que le feedback intrinsèque ?","o":["Celui qui parvient à l'individu par ses propres systèmes sensoriels, résultat de l'exécution motrice","Celui donné par le thérapeute","Le feedback terminal","La connaissance du résultat"],"r":0,"e":"Le feedback extrinsèque renforce le feedback intrinsèque.","s":7},{"q":"Qu'est-ce qui distingue pratique massée et pratique distribuée ?","o":["Le type de pauses entre les répétitions","La variété des tâches","L'ordre des répétitions","La présence de guidage"],"r":0,"e":"En pratique massée, le temps de pratique est supérieur au temps de repos.","s":7},{"q":"Quel est l'avantage de la pratique variée ?","o":["Elle facilite le transfert de l'apprentissage acquis vers de nouvelles situations","Elle améliore la performance initiale","Elle réduit la fatigue","Elle supprime le besoin de feedback"],"r":0,"e":"Elle peut être désavantageuse pendant la phase initiale d'acquisition.","s":7},{"q":"Que dit le cours sur la pratique aléatoire par rapport à la pratique structurée ?","o":["La pratique structurée donne une meilleure performance en acquisition, mais la pratique aléatoire donne une meilleure performance en phase de transfert","La pratique structurée est toujours supérieure","La pratique aléatoire est toujours supérieure","Les deux sont équivalentes"],"r":0,"e":"Les facteurs qui rendent la tâche plus difficile au début rendent souvent l'apprentissage plus effectif à long terme.","s":7},{"q":"Qu'est-ce que le transfert bilatéral ?","o":["La capacité d'acquisition et de performance de la même tâche réalisée par le membre opposé","L'influence d'une tâche sur l'apprentissage d'une autre","L'effet de la pratique isolée de composantes","Le passage du simple au complexe"],"r":0,"e":"Il repose sur la notion de programme moteur générique — par exemple écrire de l'autre main.","s":7},{"q":"Les quatre caractéristiques de l'apprentissage moteur comprennent le fait qu'il :","o":["Peut être mesuré directement","Ne peut pas être mesuré directement, ses résultats étant inférés à partir du comportement","Produit des changements immédiats","Ne dépend pas de la pratique"],"r":1,"e":"Il s'agit d'un processus d'acquisition de capacités à réaliser une action spécifique, résultant de la pratique et produisant des modifications relativement permanentes.","s":7},{"q":"Les modifications à court terme du comportement :","o":["Constituent de l'apprentissage","Ne sont pas considérées comme de l'apprentissage","Sont le seul critère valable","Précèdent nécessairement l'apprentissage"],"r":1,"e":"L'apprentissage suppose une modification relativement permanente : un gain perdu d'une séance à l'autre n'en est pas un.","s":7},{"q":"L'apprentissage moteur se définit comme un ensemble de processus associés :","o":["À la maturation neurologique","À la pratique ou à l'expérience, conduisant à des modifications relativement permanentes de la capacité à produire des actions spécifiques","À la seule répétition mécanique","À la croissance"],"r":1,"e":"Le contrôle moteur concerne, lui, les mécanismes du mouvement déjà acquis : les deux champs sont complémentaires.","s":7},{"q":"L'imitation, selon le cours :","o":["Nécessite un enseignement explicite","Permet aux bébés d'apprendre plusieurs mouvements par l'observation, sans enseignement des parents","Est propre à l'adulte","Ne produit pas d'apprentissage"],"r":1,"e":"Le cours distingue aussi l'enseignement, qui vise la transmission et peut échouer, du développement, lié à l'évolution de l'espèce.","s":7},{"q":"Le cours souligne à propos de l'enseignement qu'il :","o":["Garantit l'apprentissage","Peut y avoir tentative d'enseignement sans qu'il y ait eu apprentissage","Est synonyme d'apprentissage","Précède toujours l'apprentissage"],"r":1,"e":"Cette dissociation est décisive en rééducation : avoir expliqué un exercice ne signifie pas que le patient l'ait appris.","s":7},{"q":"L'apprentissage latent désigne :","o":["Un apprentissage en cours d'acquisition","L'incapacité à manifester objectivement, par la performance, des compétences déjà acquises","Une performance sans apprentissage","Un oubli progressif"],"r":1,"e":"Le cours cite l'exemple d'athlètes qui s'entraînent mais ne démontrent pas leurs compétences en compétition, du fait de la fatigue, de l'anxiété ou de la motivation.","s":7},{"q":"Un patient qui s'améliore pendant une séance mais n'a pas maintenu ses gains à la suivante illustre :","o":["Un apprentissage latent","Une performance sans apprentissage","Un apprentissage explicite","Un transfert"],"r":1,"e":"L'apprentissage implique des modifications plus permanentes. Le dopage est l'autre exemple donné de performance sans apprentissage.","s":7},{"q":"La principale différence entre performance et apprentissage est que la performance :","o":["Est un processus interne","Est observable, mais influencée par de nombreux facteurs","Est toujours stable","Ne dépend pas de la pratique"],"r":1,"e":"L'apprentissage est un processus interne, évalué par des démonstrations relativement stables : perfectionnement, cohérence, persistance.","s":7},{"q":"L'apprentissage implicite non associatif comprend :","o":["L'habituation et la sensibilisation","Les conditionnements classique et opérant","L'apprentissage procédural","L'apprentissage déclaratif"],"r":0,"e":"L'apprentissage implicite associatif recouvre les conditionnements ; l'apprentissage explicite, ou déclaratif, mobilise le cortex et l'hippocampe.","s":7},{"q":"L'apprentissage explicite, ou déclaratif, mobilise :","o":["Le cervelet et les noyaux gris centraux","Le cortex et l'hippocampe","La moelle épinière","Le tronc cérébral"],"r":1,"e":"Il s'oppose à l'apprentissage implicite, dont la forme procédurale sous-tend les habiletés motrices acquises sans verbalisation.","s":7},{"q":"La phase cognitive de l'apprentissage moteur dure :","o":["De quelques minutes à quelques jours","Des semaines à des mois","Des années","Toute la vie"],"r":0,"e":"La phase associative dure des semaines à des mois, la phase autonome des années. Les trois se succèdent sans frontière nette.","s":7},{"q":"La phase autonome de l'apprentissage moteur se caractérise par :","o":["Une forte charge attentionnelle","Une exécution largement automatisée, libérant les ressources attentionnelles","Des erreurs fréquentes","Un besoin d'instruction constante"],"r":1,"e":"Elle s'installe sur des années de pratique. C'est ce qui permet, par exemple, de conduire tout en tenant une conversation.","s":7},{"q":"Parmi les facteurs préalables de l'apprentissage moteur, le cours cite :","o":["L'instruction et la démonstration, l'échauffement, la motivation, l'anticipation, l'émotion et les caractéristiques de la tâche","La fatigue","Le feedback","La pratique motrice"],"r":0,"e":"Les facteurs concomitants sont la pratique motrice et la fatigue ; les facteurs postérieurs relèvent de l'information de retour sur le résultat.","s":7},{"q":"L'information de retour, ou feedback, est classée dans les facteurs :","o":["Préalables","Concomitants","Postérieurs","Externes"],"r":2,"e":"Elle intervient après l'exécution et oriente l'essai suivant : c'est le principal levier pédagogique dont dispose le rééducateur.","s":7},{"q":"Le cours énonce que ce qui rend la tâche plus difficile en phase initiale :","o":["Compromet définitivement l'apprentissage","Rend souvent l'apprentissage plus effectif à long terme","N'a aucun effet","Doit être systématiquement évité"],"r":1,"e":"Pratique variée, pratique aléatoire et apprentissage par la découverte dégradent la performance immédiate mais améliorent la rétention et le transfert.","s":7},{"q":"La pratique aléatoire, comparée à la pratique en blocs :","o":["Donne de meilleurs résultats immédiats","Donne de moins bons résultats immédiats mais une meilleure rétention à long terme","Est équivalente","Empêche l'apprentissage"],"r":1,"e":"C'est l'un des paradoxes majeurs de l'apprentissage moteur : la performance observée en séance est un mauvais indicateur de ce qui restera.","s":7},{"q":"La performance est décrite comme :","o":["Un processus interne","L'indicateur objectif du niveau d'apprentissage","La cause de l'apprentissage","Indépendante de l'apprentissage"],"r":1,"e":"Elle en est l'indicateur, mais un indicateur imparfait : elle peut surestimer l'apprentissage comme le sous-estimer, selon les circonstances.","s":7},{"q":"Le développement, distingué de l'apprentissage, est défini comme :","o":["Le perfectionnement des compétences, concept lié à l'évolution de notre espèce","L'acquisition d'une habileté particulière","La transmission de connaissances","La maturation osseuse"],"r":0,"e":"Le cours distingue ainsi quatre notions voisines : apprentissage, imitation, enseignement et développement.","s":7},{"q":"L'apprentissage, au sens général, est défini comme :","o":["Un processus d'acquisition de connaissances sur le monde qui nous entoure","Une modification génétique","Une adaptation musculaire","Un réflexe conditionné"],"r":0,"e":"L'apprentissage moteur en constitue une forme particulière, orientée vers la production d'actions spécifiques.","s":7},{"q":"Une habileté acquise en phase associative se caractérise par :","o":["Des erreurs grossières et une forte variabilité","Une réduction progressive des erreurs et de la variabilité, sur des semaines à des mois","Une automatisation complète","Une absence de progrès"],"r":1,"e":"Elle s'intercale entre la phase cognitive, où le sujet comprend la tâche, et la phase autonome, où l'exécution devient automatique.","s":7}]};
